$string['settings:embed_apikey_desc'] = 'Igodo API maka onye na-enye embedding. Ọ nwere ike ịdị iche n\'igodo API chat. Achọghị ya maka Ollama.';
$string['settings:embed_dimensions'] = 'Obosara Embedding';
$string['settings:embed_dimensions_desc'] = 'Obosara vector embedding, nke ga-abụ obosara model ahụ na-enye n\'ezie. OpenAI text-embedding-3-small: 1536. nomic-embed-text: 768. Model Voyage na-anabata 256, 512, 1024 na 2048 (a na-ewepụ 1024 ọdịnala n\'arịrịọ); a na-ewepụ obosara na-ezighị ezi kama izipu ya, ya mere ị gaara nweta obosara ọdịnala na nzuzo kama nke ị rịọrọ. voyage-4-large na 2048 bụ nhazi a tụrụ — recall +14.0 isi pesent na query ndị bara uru, n\'okpuru $4 kwa ọnwa — na ịnabata ya chọrọ INDEX ỌZỌ ZURU EZU, n\'ihi na onye nweghachi na-ajụ inye query akara megide chunk sitere n\'ohere embedding dị iche. Jiri mbufe model embedding n\'ibe index RAG kama ịgbanwe uru a mbụ.';
$string['settings:embed_model'] = 'Model Embedding';
$string['settings:embed_model_desc'] = 'Model a ga-eji mepụta embedding. Ndabara OpenAI: text-embedding-3-small. Ihe atụ Ollama: nomic-embed-text.';
$string['settings:embed_provider'] = 'Embedding Provider';
