$string['settings:model_desc_dynamic'] = 'Leave blank to use the provider\'s default model automatically. Each provider has a built-in default that stays current (e.g. gpt-4o for OpenAI, claude-sonnet-4 for Claude, mistral-large-latest for Mistral). Only enter a model name if you want to override the default. If a model is misspelled or deprecated, [[tutorshort]] will automatically fall back to the provider\'s default.';
$string['settings:provider_gemini'] = 'Google Gemini';
$string['settings:quiz_hide_heading'] = 'Quiz Page Visibility';
$string['settings:quiz_hide_heading_desc'] = 'Control whether the [[tutorshort]] widget appears on Moodle quiz pages. This is stricter than the built-in summative quiz lock, which only disables chat during graded quizzes. These settings completely hide the widget on all quiz pages.';
$string['settings:rag_chunksize'] = 'Nha Chunk (okwu)';
$string['settings:rag_chunksize_desc'] = 'Ọnụọgụ okwu e bu n\'obi kwa chunk ọdịnaya mgbe a na-etinye ihe kọọsị n\'index. Chunk ndị pere mpe ziri ezi karịa; chunk ndị buru ibu na-enye ihe gbara ya gburugburu karịa.';
$string['settings:rag_return_scope'] = 'Ogo mmughari nweta ozi';
$string['settings:rag_return_scope_desc'] = 'Ihe a ga-etinye maka nweta ozi ọ bụla achọtara. "chunk" (default) na-etinye mpempe ihe odide dị ka okwu 400 dabara. "window" na-etinye mpempe ahụ dabara na mpempe ndị agbata ya si otu ibe ahụ. "page" na-etinye ibe modul zuru ezu ebe nkwekọ ahụ dị. window/page na-enyere aka mgbe azịza gbasara otu ibe, kama ọ na-eme ka prompt buru ibu karịa.';
$string['settings:rag_window_size'] = 'Nha windo nweta ozi';
$string['settings:rag_window_size_desc'] = 'Maka ogo nweta "window": ọnụ ọgụgụ mpempe agbata a ga-etinye n\'akụkụ ọ bụla nke mpempe dabara. Default 1.';
$string['settings:rag_parent_max_chars'] = 'Oke ngalaba nne (mkpụrụedemede)';
$string['settings:rag_parent_max_chars_desc'] = 'Ọnụ ọgụgụ mkpụrụedemede kacha elu maka ngalaba window/page gbasawara. Ibe ndị gafere oke ga-alaghachi na window, wee laghachi na naanị otu mpempe. Default 6000.';
$string['settings:rag_enabled'] = 'Gbanye RAG (Nchọta Semantic)';
$string['settings:rag_enabled_desc'] = 'Mgbe e gbanyere ya, nkuzi AI na-eji nchọta semantic weta ọdịnaya kọọsị dabara maka ajụjụ ọ bụla kama ịkwanye ọdịnaya niile n\'ime prompt sistemu.';
$string['settings:rag_heading'] = 'RAG / Nchọta Semantic';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: tinye ọdịnaya kọọsị n\'index dị ka embedding ma weta naanị chunk ndị kacha dabara n\'oge ajụjụ. Ọ na-ebelata ojiji token ma na-akwado ụdị ọdịnaya niile. Ọ chọrọ API embedding.';
$string['settings:rag_topk'] = 'Chunk Top-K';
$string['settings:rag_topk_desc'] = 'Number of most relevant chunks to retrieve per user query and inject into the system prompt.';
$string['settings:realtime_apikey'] = 'OpenAI API Key (Voice & TTS)';
$string['settings:realtime_apikey_desc'] = 'Used for Voice Mode and the TTS speak button on messages. Leave blank to fall back to the main API key when provider is set to OpenAI.';
$string['settings:realtime_enabled'] = 'Enable Voice Mode';
