$string['settings:csp_course_pages_mode'] = 'Content-Security-Policy ibe kọọsị';
$string['settings:csp_course_pages_mode_desc'] = 'Isi CSP nhọrọ n\'ibe kọọsị ebe widget Onye Enyemaka AI Nkuzi na-arụ ọrụ. <strong>Gbanyụrụ</strong>: enweghị isi (ndabara). <strong>Akụkọ naanị</strong>: zipu <code>Content-Security-Policy-Report-Only</code> — ndị nchọgharị na-edekọ mmebi mana ha anaghị egbochi ya. Ọ bara uru maka nlele otu izu. <strong>Manye</strong>: zipu <code>Content-Security-Policy</code> — ndị nchọgharị na-egbochi isi iyi iframe na-anọghị na ndepụta ikike, nweta, na ibu ndị ọzọ dị ize ndụ. Ọ na-enyere aka ijide mmetụta nke script ọ bụla a tinyere na nhazi saịtị Additional HTML (ihe omume IBL AI / Raison na 2026-04-29). Ọ naghị emetụta ebe njedebe [[tutorshort]], nke na-ezipụ CSP siri ike karịa mgbe niile.';
$string['settings:csp_mode_off'] = 'Gbanyụrụ (enweghị isi n\'ibe kọọsị)';
$string['settings:csp_mode_report_only'] = 'Akụkọ naanị (dekọọ mmebi, agbochila)';
$string['settings:csp_mode_enforce'] = 'Manye (gbochie ibu na-anọghị na ndepụta ikike)';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = 'Ndabara usoro nkuzi';
$string['settings:pedagogy_defaults_heading_desc'] = 'Ọnọdụ ndabara saịtị niile maka njirimara usoro nkuzi ọ bụla. Gbanye njirimara ebe a, kọọsị niile ga-eketa ya ma ọ bụrụghị na kọọsị ahụ nwere nnọchi doro anya n\'ibe ntọala kọọsị [[tutorshort]] ya (manye ka ọ gbanye / manye ka ọ gbanyụọ). Mgbe e kwalitere gaa na v4.5.0, a na-ehichapụ nnọchi "manye ka ọ gbanyụọ" ọ bụla nke a tọrọ n\'uru ochie nke ndabara-gbanyụrụ bụ <code>0</code>, ka ndabara ụwa niile ọhụrụ wee rụọ ọrụ nke ọma. Ndabara gbanyụrụ — nkwalite si na v4.4.x anaghị eme ihe ọ bụla ruo mgbe onye nchịkwa gbanyere njirimara.';
$string['pedagogy:mastery'] = 'Nsochi nkà gbanyere na ndabara';
$string['pedagogy:mastery_desc'] = 'Mgbe ọ gbanyere, kọọsị ọ bụla na-eketa nsochi nkà belụsọ ma ọ bụrụ na kọọsị nwere mgbanwe nke ya. Nkà chọrọ ebumnuche mmụta a haziri ahazi — kọọsị ndị na-enweghị ebumnuche na-alaghachi azụ nwayọọ, ọ dịghị njehie.';
$string['pedagogy:socratic_mode'] = 'Ụdị Socrates gbanyere na ndabara';
$string['pedagogy:socratic_mode_desc'] = 'Mgbe ọ gbanyere, [[tutorshort]] na-eji ajụjụ malite kama inye azịza ozugbo na kọọsị ọ bụla belụsọ ma ọ bụrụ na kọọsị nwere mgbanwe nke ya.';
$string['pedagogy:worked_examples'] = 'Mmalite ihe atụ a rụchara gbanyere na ndabara';
$string['pedagogy:worked_examples_desc'] = 'Mgbe ọ gbanyere, mmalite mkparịta ụka bụ "Gosi m ihe atụ a rụchara" na-apụta na kọọsị ọ bụla belụsọ ma ọ bụrụ na kọọsị nwere mgbanwe nke ya.';
$string['pedagogy:flashcards'] = 'Kaadị mmụta gbanyere na ndabara';
