$string['pedagogy:code_sandbox'] = 'Sandbox koodu Python gbanyere na ndabara';
$string['pedagogy:code_sandbox_desc'] = 'Mgbe ọ gbanyere, sandbox Python dị n\'ime ihe nchọgharị dị maka kọọsị ọ bụla belụsọ ma ọ bụrụ na kọọsị nwere mgbanwe nke ya.';
