// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'Data ndị na-ere ahịa na ọnụahịa';
$string['settings:vendor_data_heading_desc'] = 'Njikwa maka ibe nchịkwa Vendor DPA nhọrọ na ndị editọ nnọchi nke na-enye ndị nchịkwa ohere idobe tebụl ndị na-ere ahịa e bunyere na kaadị ọnụahịa LLM ka ọ dị ọhụrụ na-edeghị koodu. Ndị editọ nnọchi abụọ ahụ bụ JSON; uru efu na-alaghachi na ndabara e tinyere n\'ime koodu nke a bunyere na ngwa a.';
$string['settings:vendor_dpa_admin_page_enabled'] = 'Gosi ibe nchịkwa Vendor DPA';
$string['settings:vendor_dpa_admin_page_enabled_desc'] = 'Mgbe ọ gbanyere, "Vendor DPA Status" na-apụta n\'okpuru Nchịkwa saịtị → Ngwa mgbakwunye → Ngwa mgbakwunye mpaghara → AI Course Assistant. Ibe ahụ na-egosi tebụl ndị na-ere ahịa agwakọtara na nnọchi dị n\'okpuru. Ndabara gbanyụrụ — ọtụtụ ndị nchịkwa achọghị elu a.';
$string['settings:vendor_dpa_overrides'] = 'Nnọchi Vendor DPA (JSON)';
$string['settings:vendor_dpa_overrides_desc'] = 'JSON object keyed by vendor id. Each value is an object whose fields override the hardcoded vendor row. Fields you do not specify fall through to the default. A new vendor key in the override is added to the table; edits apply per field. Malformed JSON is ignored at runtime — fix the parse error here when the saved value does not appear in the Vendor DPA page.';
$string['settings:rate_card_overrides'] = 'Nnọchi kaadị ọnụahịa LLM (JSON)';
$string['settings:rate_card_overrides_desc'] = 'Ihe JSON nwere igodo prefix aha model. Uru ọ bụla bụ <code>{"input": float, "output": float}</code> na USD kwa token 1,000,000. Ọ na-anọchi ntinye kaadị ọnụahịa e bunyere maka prefix ahụ. Ihe atụ: <pre>{ "gpt-4o-mini": { "input": 0.15, "output": 0.60 }, "claude-sonnet-4.6": { "input": 3.00, "output": 15.00 } }</pre> Ọ bụ naanị ọgụgụ site na v7.4.0: a ka na-agwakọta ubi a (n\'elu baseline e bunyere, n\'okpuru registry model) ka override dị adị wee nọgide na-arụ ọrụ, mana ọ dịghị ihe na-ede na ya ọzọ na ọnụahịa ọhụrụ kwesịrị ịnọ na registry model, nke na-edekọ onye tọrọ ọnụahịa ọ bụla na mgbe ọ tọrọ ya. Mmeghari kwa izu na-edochi ubi a dum na mbụ, na-ebibi ọnụahịa ọ bụla e tinyere n\'aka n\'ọsọ na-esote.';

// v4.7.0: rate-card auto-refresh.
$string['settings:rate_card_auto_refresh'] = 'Weghachite site na upstream na-akpaghị aka';
$string['settings:rate_card_auto_refresh_desc'] = 'Mgbe ọ gbanyere, ọrụ e mere atụmatụ kwa izu (Mọnde 02:30 oge sava) na-eweta JSON ọnụahịa upstream dị n\'okpuru, na-atụgharị ya gaa na schema kaadị ọnụahịa nke [[tutorshort]], ma na-ede ọnụahịa ọ bụla n\'ime registry model otu ahịrị n\'otu oge. Ndabara gbanyere — gbanyụọ ya iji kpọchie kaadị ọnụahịa na ihe e wetara ikpeazụ ma ọ bụ nke e tinyere n\'aka. A naghị eji mmeghari a dochie ọnụahịa onye nchịkwa tinyere, na ọsọ dara anaghị ede ihe ọ bụla ma ọlị; ọnọdụ mmeghari ikpeazụ na-apụta n\'okpuru bọtịnụ Weghachite ugbu a.';
$string['settings:rate_card_upstream_url'] = 'URL ọnụahịa upstream';
