$string['pedagogy:talking_avatar'] = 'Avatar na-ekwu okwu gbanyere na ndabara';
$string['pedagogy:talking_avatar_desc'] = 'Mgbe ọ gbanyere, ihuenyo avatar na-ekwu okwu na-arụ ọrụ na kọọsị ọ bụla belụsọ ma ọ bụrụ na kọọsị nwere mgbanwe nke ya. Ọ chọrọ onye na-enye a haziri ahazi (D-ID, HeyGen, Tavus, ma ọ bụ Synthesia Agents) n\'okpuru; ma ọ bụrụ na ọ dịghị, widget ahụ na-egosi ọkwa "hazie onye na-enye" ma avatar ahụ anaghị emegharị.';
$string['settings:talking_avatar_heading'] = 'Avatar na-ekwu okwu';
$string['settings:talking_avatar_heading_desc'] = 'Họrọ onye na-ere ahịa avatar na-ekwu okwu nke [[tutorshort]] na-emeghe maka ụmụ akwụkwọ mgbe e gbanyere elu avatar. [[tutorshort]] na-ebu draịva maka D-ID (streaming WebRTC kacha dị ọnụ ala), HeyGen (avatar mmekọrịta nke LiveKit na-akwado), Tavus (Conversational Video Interface nke a na-etinye ozugbo n\'ime iframe), na Synthesia Agents (ngwaahịa ejentị oge ozugbo, nke a haziri na dashboard Synthesia). Igodo + id persona nke onye ọ bụla na-enye na-apụta n\'okpuru; ọ bụ naanị onye na-enye ahọrọ ka ọ dị mkpa idejupụta. A na-enyocha SSRF maka oku ọ bụla na-apụ apụ.';
$string['settings:talking_avatar_provider'] = 'Onye na-enye avatar na-ekwu okwu';
$string['settings:talking_avatar_provider_desc'] = 'Họrọ onye na-ere ahịa nke igodo + id persona ya juputara n\'okpuru. Hapụ ya na <em>Ọ dịghị</em> ruo mgbe ụlọ ọrụ agụmakwụkwọ kwadoro ya; ndabara usoro nkuzi ka na-apụta na <em>Ndabara usoro nkuzi</em> mana widget na-egosi ọkwa nhazi kama avatar.';
$string['settings:talking_avatar_provider_none'] = 'Ọ dịghị (gbanyụrụ avatar)';
