$string['settings:avatar_rate_card_overrides'] = 'Nnọchi kaadị ọnụahịa avatar (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'Ihe JSON nwere igodo bụ onye na-enye avatar na otu ọnụahịa USD kwa nkeji. Ọ na-anọchi ọnụahịa e bunyere maka onye na-enye ahụ. Ihe atụ: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> Efu = jiri ndabara e bunyere na v4.10.0: D-ID $0.30/nkeji, HeyGen $0.50/nkeji, Tavus $0.30/nkeji, Synthesia $0.40/nkeji. Tọọ nke a n\'ọnụahịa nkwekọrịta gị ka dashboard analytics wee gosipụta ezigbo ọnụahịa nke ụlọ ọrụ agụmakwụkwọ ahụ.';
$string['settings:talking_avatar_did_webhook_secret'] = 'Nzuzo ịbịanye aka webhook D-ID';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'Nhọrọ. Mgbe e tọrọ ya, D-ID nwere ike POST ihe omume njedebe nnọkọ na <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code> nke e ji nzuzo a bịanye aka dị ka <code>X-DID-Signature</code> (hex HMAC-SHA256). Ahịrị webhook na-ebute ụzọ karịa heartbeat nke ihu ngwa. Efu = onye njikwa gbanyụrụ, heartbeat + onye na-ekpochapụ kwa elekere na-elekọta njedebe nnọkọ naanị ha.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'Nzuzo ịbịanye aka webhook HeyGen';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'Nhọrọ. Mgbe e tọrọ ya, HeyGen nwere ike POST ihe omume njedebe nnọkọ nke e ji nzuzo a bịanye aka dị ka <code>X-HeyGen-Signature</code> (hex HMAC-SHA256). Efu = onye njikwa gbanyụrụ.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'Nzuzo ịbịanye aka webhook Tavus';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'Nhọrọ. Mgbe e tọrọ ya, Tavus nwere ike POST ihe omume njedebe mkparịta ụka nke e ji nzuzo a bịanye aka dị ka <code>X-Tavus-Signature</code> (hex HMAC-SHA256). Efu = onye njikwa gbanyụrụ.';
