$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Prompt ogologo maka ụdị Socratic';
$string['settings:socratic_verbose_desc'] = 'Mgbe ọ gbanyere, kọọsị ndị nọ n\'ụdị Socratic na-anata ntụziaka mee/emela zuru ezu nke token ~600 nke e tinyere na mbụ na v3.9.30. Mgbe ọ gbanyụrụ (ndabara), ha na-anata ntụziaka otu ahịrị nke model ọgbara ọhụrụ dị n\'ịntanetị na-agbaso n\'ụzọ a pụrụ ịdabere na ya, nke na-azọpụta token ~600 kwa ntụgharị. Gbanye nke a ma ọ bụrụ na kọọsị na-agba ọsọ na model na-esighị ike nke a na-akwado n\'onwe ya nke chọrọ nkwado doro anya.';
$string['settings:prompt_budget_chars'] = 'Mmefu mkpụrụedemede nke prompt sistemu';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Oke ọdịnaya ibe dị ugbu a (mkpụrụedemede)';
$string['settings:current_page_content_maxchars_desc'] = 'Ọnụ ọgụgụ kachasị nke mkpụrụ edemede nke ederede ibe ugbu a e tinyere n\'ime nkwupụta sistemụ dị ka akụkụ "Ọdịnaya Ibe Ugbu a", mgbe RAG gbanyụrụ. Ndabara 8,000 na-eweta ajụjụ kpọmkwem nke ibe nke ọma ebe ọ na-ahapụ mmefu maka nhazi na ntụziaka. (Mgbe RAG gbara ọkụ, a na-eweta ibe kama site na iberibe ya kacha mkpa, na-ele anya n\'ibe ugbu a, yabụ oke a anaghị emetụta.) A na-egbutu ibe dị ogologo nke ukwuu site n\'isi ruo ọnụ ọgụgụ mkpụrụedemede a, yabụ enwere ike ọ gaghị ehoputa njedebe nke ibe dị ogologo nke ukwuu; ịgbanye RAG na-ezere nke ahụ. Saịtị na-eche banyere ọnụ ahịa nwere ike ịbelata ya (dịka ọmụmaatụ 3,000-4,000). Ejidere ya na oke 500-8,000. Nọọrọ onwe ya site na <code>prompt_budget_chars</code>: nke a na-amachi naanị akụkụ ibe; mmefu na-amachi nkwupụta dum.';
$string['settings:prompt_verbosity'] = 'Ogologo prompt';
$string['settings:prompt_verbosity_desc'] = 'Ogologo ndabara maka ngọngọ ntụziaka (ụdị Socratic, akụrụngwa mpụga). Mkpirikpi (ndabara) bụ nke model ọgbara ọhụrụ dị n\'ịntanetị na-agbaso n\'ụzọ a pụrụ ịdabere na ya; ọkọlọtọ na-agbakwunye nkwado doro anya maka model ndị dị n\'etiti; ogologo na-edobe ntụziaka dị arọ nke oge v3.9.30 maka model ndị na-esighị ike nke a na-akwado n\'onwe ya. Nnọchi nke kọọsị dị site na <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Mkpirikpi (a tụrụ aro maka model ndị dị n\'ịntanetị)';
$string['settings:prompt_verbosity_standard'] = 'Ọkọlọtọ';
$string['settings:prompt_verbosity_verbose'] = 'Ogologo (maka model ndị na-esighị ike a na-akwado n\'onwe ya)';
$string['settings:prompt_metrics_enabled'] = 'Jide mmetrik prompt kwa akụkụ';
$string['settings:prompt_metrics_enabled_desc'] = 'Mgbe ọ gbanyere (ndabara), ntụgharị chat ọ bụla na-ede otu ahịrị JSON maka prompt ọ bụla e jikọtara na <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code> nwere ọnụọgụ mkpụrụedemede kwa ụdị. A na-edobe ụbọchị 7 ikpeazụ. Ibe nchịkwa mmetrik na-achịkọta ndị a maka ndụmọdụ mmefu. Anaghị edekọ PII ọ bụla — naanị nha akụkụ. Gbanyụọ ya ma ọ bụrụ na ụlọ ọrụ agụmakwụkwọ gị achọghị faịlụ mmetrik ma ọlị.';
$string['settings:prompt_budget_auto_tune'] = 'Ndozi akpaaka kwa ụbọchị nke mmefu ntuziaka sistemu (akwụsịla ya)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Akwụsịla ya. Ọ naghị eme ihe ọ bụla ma ọ bụghị na ụdị mmefu dị n\'elu edobere na <strong>Edobere</strong>. Ọrụ kwa ụbọchị na-echepụta mmefu mkpụrụedemede site n\'ile anya maka mbelata na ịchụso ntuziaka kacha ukwuu ọ hụrụ. Iwepụta mmefu site na mpio ihe gbara ihe nlereanya gburugburu na-eme nke ahụ nke ọma karịa: ọ pụghị ịma jijiji, ọ chọghịkwa data mmalite. Ha abụọ mekwara mgba, n\'ihi na ọrụ ahụ na-ede mmefu mkpụrụedemede, uru ọ bụla na-abụghị ndabara na-agbanyụ mmefu ewepụtara. Hapụ nke a gbanyụọ; a ga-ewepụ ya na mwepụta n\'ọdịnihu. Ndụmọdụ ahụ ka na-apụta na peeji <a href="/local/ai_course_assistant/prompt_metrics.php">Ihe ọtụtụ ntuziaka</a>.';
