$string['empathy:title'] = 'Nkwurịta okwu obiọma na nchekwa ncheta a na-ebufe (v5.3.0)';
$string['empathy:desc'] = 'Atụmatụ atọ nke a haziri ọnụ na-eme ka [[tutorshort]] yiere onye nkuzi na-ege ntị. Ebumnobi na-ejide ihe mere onye mmụta ji nọrọ ebe a. Nchekwa ncheta a na-ebufe na-echeta ihe siri ike na mbụ ka [[tutorshort]] wee nwee ike inye ụzọ ọzọ. Akara ọganihu na-eji email ekele ụbọchị ndị gbasoro ibe ha na mmecha kọọsị. Atụmatụ ọ bụla nwere mgbanyụ nke ya, onye mmụta ga-ekwenyekwa tupu ọ malite. Akara nsogbu mmụta anaghị apụ na chat — a naghị eziga email ọ bụla banyere oge ọmụmụ siri ike.';
$string['empathy:outreach_master_enabled'] = 'Mgbanyụ ukwu maka izigara ozi';
$string['empathy:outreach_master_enabled_desc'] = 'Agbanyụrụ ya na ndabara na nrụnye ọhụrụ. Mgbe ọ gbanyụrụ, ỌDỊGHỊ email obiọma ụdị ọ bụla na-apụ ma ọlị, n\'agbanyeghị mgbanyụ nke atụmatụ ọ bụla dị n\'okpuru. Gbanye nke a naanị mgbe ị lechara ndabara nke atụmatụ ọ bụla na usoro nkwenye onye mmụta.';
$string['empathy:goals_enabled'] = 'Gbanye mkparịta ụka banyere ebumnobi ọrụ';
$string['empathy:goals_enabled_desc'] = 'Na-ekwe ka ndị mmụta nye azịza abụọ dị mkpụmkpụ n\'afọ ofufo (ihe mere ha ji nọrọ ebe a, ihe ha chọrọ ịghọ) nke na-abanye na nhazi nkeonwe. Naanị n\'ime chat; enweghị email. Ọ dị mma ịhapụ ya ka ọ na-arụ ọrụ.';
$string['empathy:milestones_enabled'] = 'Gbanye email ntụlegharị maka akara ọganihu';
$string['empathy:milestones_enabled_desc'] = 'Na-eziga email dị mkpụmkpụ nke nwere obiọma mgbe onye mmụta ruru ụbọchị 7 gbasoro ibe ha, ụbọchị 30 gbasoro ibe ha, ma ọ bụ mgbe o mechara kọọsị. Ọ chọrọ mgbanyụ ukwu dị n\'elu tinyere nkwenye nke onye mmụta ọ bụla. Oke siri ike bụ otu email kwa onye mmụta kwa ụbọchị 7 n\'ụzọ niile.';
$string['empathy:memory_enabled'] = 'Gbanye nchekwa ncheta nkeonwe a na-ebufe';
$string['empathy:memory_enabled_desc'] = 'Na-ekwe ka [[tutorshort]] buru obere ndetu nzuzo banyere ihe siri onye mmụta ike site n\'otu oge ọmụmụ ruo nke ọzọ, ka nzaghachi na-esote wee nwee ike inye ụzọ ọzọ. Enwere oke na ya (ndetu 5 kacha maka onye mmụta ọ bụla na kọọsị ọ bụla, TTL ụbọchị 90). Onye mmụta nwere ike idezi ya. Ndị nkuzi anaghị ahụ ya ma ọlị.';
$string['empathy:struggle_enabled'] = 'Gbanye ihe nkewa nsogbu mmụta';
$string['empathy:struggle_enabled_desc'] = 'Agbanyụrụ ya na ndabara. Ọ na-ekwe ka [[tutorshort]] chọpụta iwe na-adịgide n\'ọtụtụ nlọghachi ma jiri nwayọọ dekọọ ndetu banyere ebe onye mmụta rapaara n\'ime nchekwa ncheta a na-ebufe dị n\'elu. Mmepụta ya na-adị naanị n\'ime chat; a naghị eziga email ọ bụla banyere oge ọmụmụ siri ike. Ọ na-ehichapụ data akara ahụ n\'onwe ya mgbe ụbọchị 7 gasịrị.';
$string['empathy:outreach_dryrun'] = 'Nnwale izigara ozi (dekọọ ma ghara izipu)';
$string['empathy:outreach_dryrun_desc'] = 'Mgbe ọ gbanyere, ọrụ ahaziri maka akara ọganihu na-edekọ ahịrị nyocha dị ka a ga-asị na o zigara email mana ọ naghị ezigara onye ọ bụla email n\'ezie. Jiri nke a na nrụnye ọhụrụ iji nyochaa usoro ezumike na nkwenye tupu ị malite ya n\'ezie.';
