// v5.10.x strings (token-aware budgeting, backend retry, self-test, deployment presets, escalation consent, privacy).
$string['settings:backend_context_tokens'] = 'Windo ọnọdụ backend (tokens)';
$string['settings:backend_context_tokens_desc'] = 'Ogologo ọnọdụ kachasị (max_model_len) nke backend AI gị, na tokens. Tọọ ya na 0 maka ụdị ndị a na-akwado nke nwere nnukwu windo (enweghị mmachi). Mgbe etoro ya karịa 0 (dịka ọmụmaatụ 8192 na backend vLLM nke onwe gị na-akwado), [[tutorshort]] na-ebelata mmefu mkpụrụedemede nke ntinye sistemu dị n\'elu ka ntinye na mmepụta echekwara na akụkọ ihe mere eme nke mkparịta ụka dabara n\'ime windo, ọbụladị n\'asụsụ ndị tokens jupụtara. Lee ibe wiki Deployment Sizing maka otú nke a si dakọtara na ndị ọrụ na-eme ihe n\'otu oge.';
$string['settings:backend_retry_attempts'] = 'Mgbalị ịnwalegharị backend';
$string['settings:backend_retry_attempts_desc'] = 'Ugboro ole ka a ga-anwalegharị njehie backend nwa oge (HTTP 429 ma ọ bụ 503) tupu igosi nwa akwụkwọ njehie. Ịnwalegharị na-eme naanị tupu e bufee ederede nzaghachi ọ bụla, ya mere a naghị emepụtagharị mmepụta. E mere ya maka backends ndị nta nke onwe gị na-akwado nke na-ajụ arịrịọ n\'okpuru ibu. Tọọ ya na 0 iji gbanyụọ. Ndabara 2.';
$string['settings:backend_retry_max_wait'] = 'Oge nchere kachasị nke ịnwalegharị backend (sekọnd)';
$string['settings:backend_retry_max_wait_desc'] = 'Oke elu, na sekọnd, kan ogologo oge a ga-asọpụrụ isiokwu Retry-After site na backend tupu ịnwalegharị. Mgbe backend na-ezighị Retry-After, [[tutorshort]] na-eji obere nlaghachi azụ kọlọ kama. Ndabara 5.';
$string['prompt:truncation_hint'] = 'RỊBA AMA: Enweghị ike ịchọ ọdịnaya kọọsụ niile na nzaghachi a n\'ihi mmachi ogologo. Ọ bụrụ na nwa akwụkwọ jụọ banyere ihe ị na-apụghị ịchọta n\'ọdịnaya e nyere, kwuo na ị nweghị ike ịchọ kọọsụ niile ma tụọ aro ka ha mepee ibe ma ọ bụ ọrụ kpọmkwem ebe e kpuchiri isiokwu ahụ, kama ikwu na ọ dịghị na kọọsụ ahụ.';
$string['selftest:title'] = 'Nyocha onwe backend';
$string['selftest:intro'] = 'Gbaa nyocha dị ndụ nke backend AI ahaziri gị: obere njegharị mkparịta ụka, nchọpụta akpaaka nke windo ọnọdụ (max_model_len) na ntụnyere megide ntọala Windo ọnọdụ backend gị, ala mmefu nke ntinye sistemu, na (mgbe RAG dị) njegharị embedding. Oku netwọk na-agba naanị mgbe ị pịrị Gbaa.';
