$string['coursesettings:apibaseurl_rejected'] = 'E chekwaghị URL ntọala API: ọ ga-abụrịrị ebe njedebe HTTPS ọha nke na-agafe nyocha nchekwa SSRF.';
$string['settings:escalation_intent_patterns'] = 'Ụkpụrụ ebumnobi mbulite';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. Otu okwu ọdịnala n\'ahịrị ọ bụla; a na-eleghara ahịrị ndị na-amalite na #. A na-emepe tiketi nkwado naanị mgbe ozi nke onye mmụta n\'onwe ya dabara na otu n\'ime ndị a, ka ọdịnaya nkuzi ghara ịkpalite mbulite n\'aha onye mmụta. Hapụ ya efu iji jiri ndabara ndị e wuru n\'ime, nke na-ekpuchi Bekee tinyere ụfọdụ okwu ndị a na-ejikarị eme ihe na Spanish, French, German na Portuguese. Saịtị ndị ụmụ akwụkwọ ha na-ede n\'asụsụ ọzọ kwesịrị ịgbakwunye ụkpụrụ ebe a: ozi na-adabaghị pụtara na a gaghị emepe tiketi.';
$string['settings:zendesk_require_consent'] = 'Chọọ nkwenye tupu mbuli elu nkwado';
$string['settings:zendesk_require_consent_desc'] = 'Mgbe ọ gbanyere (akwadoro), [[tutorshort]] na-ebuli mkparịta ụka elu na tebụl nkwado Zendesk naanị mgbe onye mmụta nabatara ọkwa nkwenye nke mbụ, nke na-ekpughe na ịrịọ enyemaka mmadụ na-ekekọrịta mkparịta ụka (gụnyere aha na email) na nkwado. Gbanyụọ nke a naanị ma ọ bụrụ na ị nwetara nkwenye ahụ n\'ụzọ ọzọ; mgbe ọ gbanyụrụ, a na-eziga mbuli elu ozugbo. Ọ naghị enwe mmetụta belụsọ na e nyere mbuli elu Zendesk ike.';
$string['chat:escalation_needs_consent'] = 'O yiri ka nke a chọrọ otu onye nke ndị otu nkwado anyị. Iji nyefee ya, m ga-ekekọrịta mkparịta ụka a, gụnyere aha gị na email gị, na tebụl nkwado. Ị kwekọrọbeghị na nke ahụ, ya mere ezighị m ihe ọ bụla. Ọ bụrụ na ịchọrọ enyemaka mmadụ, biko nabata ọkwa nkekọrịta data maka onye enyemaka a ma jụọ ọzọ, ma ọ bụ kpọtụrụ nkwado kpọmkwem.';
$string['privacy:metadata:email_optout'] = 'Mmasị ịpụ na email nke onye nnata ọ bụla (ụdị email ndị onye nnata kwụsịrị ịde aha na ya).';
$string['privacy:metadata:email_optout:email'] = 'Adreesị email onye nnata nke ịpụ metụtara.';
$string['privacy:metadata:email_optout:optout_type'] = 'Ụdị email nke onye nnata pụrụ na ya.';
$string['privacy:metadata:email_optout:userid'] = 'Onye ọrụ Moodle nke ịpụ bụ nke ya, mgbe amaara ya.';
$string['chat:consent_scroll_hint'] = 'Biko pịgharịa gaa n\'okpuru iji gụọ ọkwa ahụ n\'ozuzu ya tupu ịga n\'ihu.';
$string['settings:rag_min_similarity'] = 'Mkpa kacha nta (cosine)';
$string['settings:rag_min_similarity_desc'] = 'Na-atụfu iberibe e wetara nke myirịta cosine ya na ajụjụ dị n\'okpuru uru a, ka ajụjụ na-adịghị emetụta isiokwu maọbụ nke pere mpe wụnye mpaghara ole na ole (maọbụ efu) kama ijuputa mgbe niile ruo Top-K na ndakọrịta na-esighị ike. Oke site na 0 ruo 1; 0 na-agbanyụ ọnụ ụzọ ama. Uru ziri ezi dabere na ụdị embedding: 0.25 dabara text-embedding-3-small. Bulie ya ka ọ sie ike (obere, ihe gbasara isiokwu karịa), wedata ya ka ọ na-enye ohere karịa.';
$string['settings:rag_currentpage_boost'] = 'Mmụba ibe ugbu a';
$string['settings:rag_currentpage_boost_desc'] = 'Obere mmụba e tinyere na akara mkpa nke iberibe sitere n\'ibe nke onye mmụta na-ele anya ugbu a, ka ajụjụ ndị dị ka "kọwaa nke a" họrọ ibe a na-ahụ anya mgbe akara dị nso. Naanị usoro: ọ naghị amanye iberibe ibe na-enweghị mkpa ka ọ gafee ọnụ ụzọ ama mkpa kacha nta. Tọọ 0 iji gbanyụọ.';
$string['settings:history_mode'] = 'Ọnọdụ nhọrọ akụkọ ihe mere eme';
$string['settings:history_mode_desc'] = 'Otú e si ahọrọ ntụgharị mkparịta ụka gara aga tupu e zigara ya ụdị. <strong>Pụtara ihe</strong> na-edobe naanị ntụgharị nso nso ndị metụtara ajụjụ ugbu a (na mgbe niile mgbanwe nke ọhụrụ), ka ntụgharị mbụ ochie nke na-adịghị emetụta isiokwu ghara ịbawanye ọnụ ahịa maọbụ wepụ azịza n\'ụzọ; ọ na-eme otu oku embedding ọzọ kwa ozi. <strong>Ọhụrụ</strong> na-edobe ụzọ abụọ ikpeazụ nke "Akụkọ Mkparịta Ụka Kacha" n\'agbanyeghị mkpa (omume ogologo oge, enweghị oku ọzọ). Ọ bụrụ na embedding adịghị, ọnọdụ pụtara ihe na-alaghachi na ọhụrụ na-akpaghị aka.';
$string['settings:history_mode_semantic'] = 'Pụtara ihe (ntụgharị nso nso ndị dị mkpa)';
$string['settings:history_mode_recency'] = 'Ọhụrụ (ụzọ abụọ N ikpeazụ)';
$string['settings:history_semantic_minscore'] = 'Ala ala mkpa akụkọ (cosine)';
$string['settings:history_semantic_minscore_desc'] = 'N\'ọnọdụ akụkọ pụtara ihe, a na-edobe ntụgharị gara aga naanị ma ọ bụrụ na myirịta ya na ajụjụ ugbu a opekata mpe ha uru a (mgbe niile a na-edobe mgbanwe nke ọhụrụ). Oke site na 0 ruo 1; dabere na ụdị. Bulie ka ọ sie ike (obere akụkọ), wedata iji debe karịa.';
$string['settings:history_candidates'] = 'Windo ndị na-azọ akụkọ';
$string['settings:history_candidates_desc'] = 'N\'ọnọdụ akụkọ pụtara ihe, naanị ọnụ ọgụgụ a nke ụzọ abụọ nso nso ka a na-enye akara maka mkpa (oke ọnụ ahịa). A naghị eziga ụzọ abụọ ndị ochie karịa windo a. Debe nke a na ma ọ bụ n\'elu "Akụkọ Mkparịta Ụka Kacha".';

