$string['emergency:flag_chat'] = 'Chat';
$string['emergency:flag_chat_desc'] = 'Ọ na-akwụsị oku AI [[tutorshort]] niile — mkparịta ụka, ajụjụ, kaadị mmụta na inye akara — maka ndị mmụta, ndị nchịkwa na ọrụ e hazitere otu aka. Widget ahụ ka na-egosi, ndị mmụta na-ahụ ozi nkwụsịtụ dị mkpirikpi. Nnwale onwe azụ na nyocha ahụike ka dịpụta ka i nwee ike nyochaa onye na-eweta tupu iweghachi.';
$string['emergency:flag_voice'] = 'Olu';
$string['emergency:flag_voice_desc'] = 'Na-ekpochapụ onye na-enye olu na-arụsi ọrụ ike (echekwara maka nweghachi ziri ezi). Chat ederede na-aga n\'ihu na-arụ ọrụ.';
$string['emergency:flag_rag'] = 'RAG';
$string['emergency:flag_rag_desc'] = 'Na-gbanyụọ nweghachi na indexing. Chat na-aga n\'ihu n\'enweghị nchedo nke ọdịnaya kosi.';
$string['emergency:flag_outreach'] = 'Nrubeọnụ';
$string['emergency:flag_outreach_desc'] = 'Na-akwụsị digest, ihe nnweta, na email ihe ncheta. Anaghị emetụta chat.';
$string['emergency:flag_all'] = 'IHE MGBANYỤ ISI';
$string['emergency:flag_all_desc'] = 'Na-gbanyụọ plugin n\'ozuzu ya: widget apụọ n\'ibe ọ bụla, ọrụ nhazi kwụsịrị, olu ewepụrụ, RAG gbanyụọ, nrubeọnụ gbanyụọ. Mgbanwe kachasị ike — jiri maka ihe mberede nchedo ma ọ bụ mgbe a ga-ewere [[tutorshort]] offline ozugbo.';
$string['emergency:settings_link'] = 'Njikwa ihe mberede';
$string['emergency:settings_link_desc'] = 'Mgbanwe ihe mgbanyụ kwa usoro (chat / olu / RAG / nrubeọnụ / isi) na nlekọta nyocha — nha weebụ nke <code>admin/cli/emergency_disable.php</code>. Mepee <a href="{$a}">Njikwa Ihe Mberede [[tutorshort]]</a>.';
$string['email_unsubscribe:done_title'] = 'Fụọ aha';
$string['email_unsubscribe:done_body'] = 'Emechara — {$a->email} agaghị ọzọ nata ụdị email a si n\'aka {$a->product}. Ọ bụrụ na ị gbanwee uche gị, rịọ onye nlekọta {$a->product} ka ha weghachi ndebanye aha, ma ọ bụ ziga nkwenye ọhụrụ site na ibe admin Ndị Nnata [[tutorshort]].';
$string['email_unsubscribe:invalid_title'] = 'Njikọ nweghachi aha adịghịkwa mma';
$string['email_unsubscribe:invalid_body'] = 'Njikọ nweghachi aha a apuchala ma ọ bụ enweghị nhazi ziri ezi. Chọọ email nke ọhụrụ site n\'aka anyị, ma ọ bụ kpọtụrụ onye nlekọta ọnọdụ ka ewepụ gị n\'aka.';
$string['settings:prompt_proportions_heading'] = 'Oke akụkụ prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Kesaa ihe oge prompt sistemụ n\'ime ite anọ: nchedo + njirimara, nhazi kosi, ọdịnaya kosi, na ibe ugbu a. Ibu bụ pasent na-akopụta ruo 100. Ndabara ndị etunye site na ule (10 / 10 / 40 / 40) si n\'ule ntunye ibu v5.6.0; ọ bụrụ na ahapụ ohere ederede ọcha na-eji ndabara ndị ahụ. Mmụba akpaaka na-ahazi mkesa kwa ugboro dabere na ma ibe a pụtara ìhè nwere nha.';
$string['settings:prompt_section_weights'] = 'Ibu akụkụ ntọala (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Ihe JSON ọ bụ nhọrọ na-ezochiite ite ọ bụla na pasent. Hapụ ọcha iji jiri ndabara ndị ule ule (10 / 10 / 40 / 40). Ihe atụ: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Ibu ga-akopụta ruo 100 (±5%). <code>safety_identity</code> nwere ala 10% ka jailbreak ntaramahụhụ na akara usọmpi ọdịnaya na-abalanye n\'ozuzu. <code>current_page + course_content</code> kwesịrị ịnọ opekata mpe 40% ka model nwee ihe dị arụ isi iji nọdụ ụlọ na. Ụkpụrụ n\'èzí oke na-aghachi n\'ụzọ jụụ na ndabara ule ule; ndị nlekọta kwesịrị iji lelee log debug prompt mgbe echekwara ịgụnyere.';
$string['settings:prompt_context_boost_mode'] = 'Ụdị mmụba kontekst';
$string['settings:prompt_context_boost_mode_desc'] = 'Nhazi akpaaka na-awụga ibu n\'akụkụ ibe ugbu a mgbe ibe pụtara ìhè nwere nha, ma n\'ọdịnaya kosi mgbe a họọbeghị ibe. <strong>page_focus</strong> (ndabara) na-awụga ihe dịka ihe ìnyìnyà ibu 15. <strong>aggressive</strong> na-awụga ihe ìnyìnyà 25 ma ọ kacha mma mgbe ndị mmụta na-ajụ ajụjụ pụtara ìhè ibe n\'ụzọ kwuruakwu. <strong>off</strong> na-gbanyụọ mmụba; ibu ntọala ndị nlekọa tọrọ na-arụ ọrụ n\'ugboro ọ bụla n\'ala kontekst ibe.';
$string['settings:prompt_context_boost_off'] = 'Gbanyụọ (jiri ibu ntọala n\'ugboro ọ bụla)';
$string['settings:prompt_context_boost_page_focus'] = 'Afọchafu ibe (ndabara, ~ìnyìnyà ihe ìnyìnyà 15)';
$string['settings:prompt_context_boost_aggressive'] = 'Ike ukwu (~ìnyìnyà ihe ìnyìnyà 25)';
$string['settings:prompt_section_weights_coach'] = 'Gbanwee ibu ụdị onye nkuzi (JSON, nhọrọ)';
$string['settings:prompt_section_weights_coach_desc'] = 'Ihe JSON ọ bụ nhọrọ na-agbagha ibu akụkụ ntọala n\'oge ụdị onye nkuzi quiz nwere uru (mgbe <code>quizmode=coach</code>). Bara uru maka iji mkpali mkesa <code>current_page</code> dị arọ n\'oge quiz n\'enweghị imetụta chat nkịtị. Hapụ ọcha iji nọgide na ibu ntọala. Iwu nyocha ndị ahị dịka ntọala ntọala.';
$string['prompt_debug_view:title'] = 'Onye nlele log debug prompt';
$string['prompt_debug_view:subtitle'] = 'Sistemụ prompt hazie kwa ugboro + nkewa kwa akụkụ + akụkọ ihe mere eme mkparịta ụka + ozi onye ọrụ ugbu a + metadata ngekwapụ, dị ka model natara ya. Jiri nke a iji nyochaa ma akụkụ dị ka Ọdịnaya Ibe Ugbu a ruru n\'ime prompt na iji dozie nsogbu àgwà azịza n\'enweghị SSH n\'ọnọdụ.';
$string['prompt_debug_view:disabled'] = 'Igede log debug prompt dị GBANYỤỌ ugbu a. A gaghị ede mbidu ọhụrụ ruo mgbe ọ gbanyere.';
$string['prompt_debug_view:enable_link'] = 'Mepee ntọala plugin iji gbaa "Deghere sistemụ prompt hazie na faịlụ".';
$string['prompt_debug_view:no_log_yet'] = 'Faịlụ log adịghị ka ugbu a. Zipu ma ọ dị opekata mpe otu ugboro chat mgbe ịgbanye log debug; a na-emepụta faịlụ ahụ n\'ide mbụ.';
