$string['settings:mastery_classifier_provider'] = 'Onye na-enye classifier';
$string['settings:mastery_classifier_provider_desc'] = 'ID onye na-enye ejiela maka classifier nkwado kwa ugboro. Hapụ ọcha iji nọgide na onye na-enye AI ndabara. <code>openai</code> ndabara na-ejikọta na model classifier <code>gpt-4o-mini</code> n\'okpuru — nhọrọ kacha eru onu TIER 1 maka nhazi ọdịnaya haziri azu (~nchekwa $220 n\'ọnwa na MAU 100k vs ọkwa chat). Mgbe atọrọ, ahịrị na Ndị na-enye tụnyere nwere ID onye na-enye a na-enye igodo API, URL ntọala, na okpomọkụ.';
$string['settings:premium_escalation_heading'] = 'Ọkwa mmụba elu (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Nhọrọ ụzọ kwa ugboro gaa n\'model elu (Claude Opus 4.8 site na ndabara) maka prompt ebe ọkwa chat isi na-apụ ihe ike n\'ụzọ a na-ahụ anya — na-abụkarị mgbakọ na mwepụ ọtụtụ ọkwa, CS, na nghọta sayensị. Ihe nchọpụta bake-off A.10 nke 2026-06-09: Opus 4.8 meriri na 14.97/15 vs 12.68/15 nke gpt-4o n\'elu prompt siri ike. Ụzọ abụọ kpalie: regex kwekọọ na ozi onye ọrụ, MA ọ BỤ ndepụta ikike kosi na-eme mmụba kwa ugboro. Gbanyụọ site na ndabara. Na ~5% mmụba, tụọ ~$700 n\'ọnwa na MAU 100k [[unishort]] n\'elu ihe eji eme chat ntọala.';
$string['settings:premium_escalation_enabled'] = 'Gbaa ụzọ mmụba elu';
$string['settings:premium_escalation_enabled_desc'] = 'Mgbe ọ gbanye, router kwa ugboro na-enyocha ndepụta regex kpaliri na ndepụta ikike kosi maka oku chat ọ bụla; ugboro kwekọọ na-aga n\'onye na-enye elu. Na-alata n\'onye na-enye isi ma ahịrị elu fọdụbeghị ma ọ bụ daa ịhọta. Admin-LLM-picker gbanweere na-emerịọ na-arụ ọrụ n\'enweghị ntụleghachi.';
$string['settings:premium_escalation_provider'] = 'Onye na-enye elu';
$string['settings:premium_escalation_provider_desc'] = 'ID onye na-enye iji duzie oku elu. Kwesịrị ịhụ ahịrị na Ndị na-enye tụnyere (ka igodo API, URL ntọala, na okpomọkụ si n\'otu ebe ndị nlekọta na-ahazi). Ndabara <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Model elu';
$string['settings:premium_escalation_model_desc'] = 'Aha model nyefere onye na-enye elu. Ndabara <code>claude-sonnet-5</code> dị ka mkpebi bake-off A.10.';
$string['settings:premium_escalation_triggers'] = 'Regex ihe kpalie elu';
$string['settings:premium_escalation_triggers_desc'] = 'Otu PCRE regex kwa ahịrị (n\'enweghị delimiters; ijikwa mkpachaahụ na-arụ ọrụ n\'otu aka). Ahịrị ndị na-amalite na # bụ ọdeyitọ. Hapụ ọcha iji jiri ihe ntọala edobere site na bake-off A.10 (akara STEM ọtụtụ ọkwa: "derive", "prove that", "step by step", mgbakọ LaTeX, blọọkị koodu akpuchiri, big-O, integral, nhazi, wdg.).';
$string['settings:premium_escalation_course_tags'] = 'Ndepụta ikike kosi elu';
$string['settings:premium_escalation_course_tags_desc'] = 'Otu aha mkpirisi kosi ma ọ bụ isi idnumber kwa ahịrị. Ugboro ọ bụla na kosi kwekọọ na-eme mmụba n\'otu aka n\'ala regex ozi (jiri ya maka kosi siri ike STEM ebe mmụba kwesịrị ịbụ ndabara). Ijikwa bụ isi na-anaghị ahụ ụdị ukwu - "MATH" kwekọrọ MATH121, MATH205, wdg.';
$string['settings:spend_cap_per_course_default'] = 'Oke ihe eji kosi kwa kosi ndabara (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Oke nchedo etinyere kosi ọ bụla nwere oke ihe eji kwa kosi nke nwere nnọchiteanya ya. Tọọ ihe atụ <code>30</code> iji gbochi ihe eji kosi ọ bụla n\'ọnwa na $30 n\'enweghị ịhazi kosi ọ bụla. <code>0</code> = enweghị ndabara (naanị oke n\'ọnọdụ n\'ozuzu ya na oke gbanweere kwa kosi na-arụ ọrụ). Mgbe kosi gabiga 80% / 95% / 100% nke oke a, usoro ọkwa spend-guard dị ugbu a na-eziga ozi nlekọta (ndepụta nnata: <code>spend_notify_emails</code>, na-alata n\'ndị nlekọta ọnọdụ). Kosi dị iche iche nwere ike oge ọ bụla ibulite elu ruo n\'okpuru ya site na ịtọ oke gbanweere dị elu.';
$string['settings:cost_anomaly_heading'] = 'Onye nchọpụta ihe ọjọọ ọnụahịa (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Ọrụ nhazi kwa ụbọchị (<code>cost_anomaly_check</code>) nke na-atụ ihe eji ọnọdụ n\'ozuzu [[tutorshort]] taa na median ịgba ọsọ 7-ụbọchị. Na-eziga email na ndepụta nnata <code>spend_notify_emails</code> (na-alata n\'ndị nlekọta ọnọdụ) mgbe taa gaara ihe dị oke × median. Na-enwe ụdị ihe daa atọ ndị oke 80% / 95% / 100% dị ugbu a gbafuoro: (1) kosi ọsọ ọsọ ebe oke dị elu n\'ozuzu ya azụrụ ọ bụ kosi otu na-akpali ihe 10x ọ bụ na ya n\'ọsọ nkịtị ya, (2) igba ụzọ tier elu n\'ihe ọjọọ, (3) misroute onye na-enye. Gbanyụọ site na ndabara; nha n\'ime-[[tutorshort]] nke ajụjụ Redash na <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Gbaa onye nchọpụta ihe ọjọọ ọnụahịa';
$string['settings:cost_anomaly_enabled_desc'] = 'Mgbe ọ gbanye, ọrụ nhazi kwa ụbọchị na-enyocha ihe eji taa megide median ịgba ọsọ 7-ụbọchị ma na-eziga ndị nlekọta email n\'ihe ọjọọ. Ụbọchị 7 mbụ mgbe ịgbaa na-emepụta ọnọdụ <code>insufficient_history</code> (enweghị ntọala akụkọ ihe mere eme ka ugbu a) ma emezighaghị ọkwa ọzọ. Idempotent kwa ụbọchị: flag na <code>config_plugins</code> na-egbochi email ugboro ole na ole ma cron na-agba ọsọ ọtụtụ ugboro.';
$string['settings:cost_anomaly_multiplier'] = 'Ihe na-abawanye ihe ọjọọ';
$string['settings:cost_anomaly_multiplier_desc'] = 'Ihe eji taa kwesịrị igafe ihe na-abawanye a × median 7-ụbọchị iji kpalie ọkwa ọzọ. Ndabara <code>2.0</code>. Belata na <code>1.5</code> maka ọkwa ọzọ mbụ (ọtụtụ ihe odụdụ ụgha n\'oge mmụba ndebanye aha). Bulie na <code>3.0</code> ma ọ bụrụ na ojiji [[unishort]] na-aburstị nke ọma n\'ụzọ na-emepụta spikes 2x na-abụkarị.';
$string['task:cost_anomaly_check'] = 'Nlele ihe ọjọọ ọnụahịa [[tutorshort]] (kwa ụbọchị)';
// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Signed policy bundle (mgbanwe omume site n\'ebe ọzọ)';
$string['settings:policy_bundle_heading_desc'] = 'Tinye ntọala omume (prompts, routing, escalation triggers, RAG tuning, spend policy) sitere na cryptographically signed JSON file n\'enweghị code deploy. Ọrụ nke amaokwa kwa ụbọchị na-eweta bundle URL, na-atụ aro Ed25519 signature ya megide public key dị n\'okpuru, ma tinye ntọala naanị ma ọ bụrụ na igodo ọ bụla dị na built-in allowlist ma ụdị bundle dịkwuo ọhụrụ karịa nke ikpeazụ etinyere. Igodo API, URL, webhooks, na ntọala nchekwa enweghị ike itoọ bundle. Mepụta ma bịanye aka na bundles site na <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'Kwado policy bundle sync';
$string['settings:policy_bundle_enabled_desc'] = 'Mgbe etinyelachara ya, ọrụ kwa ụbọchị na-eweta ma tinye bundles ndị e bịanyere aka. Agbanyụọla na ndabara. Ịgbanyụ ya na-akwụsị sync niile ozugbo; ntọala ndị etinyela dị na ha ugbu a.';
$string['settings:policy_bundle_url'] = 'Policy bundle URL';
$string['settings:policy_bundle_url_desc'] = 'URL HTTPS nke signed bundle JSON (dịka ihe S3 ma ọ bụ GitHub raw URL). URL na-aga site na SSRF validation otu ahụ dị ka AI provider endpoints; ụlọ ọrụ private-network ma ọ bụ plain-http chọrọ ntinye na SSRF trusted endpoints allowlist.';
$string['settings:policy_bundle_pubkey'] = 'Policy bundle public key';
$string['settings:policy_bundle_pubkey_desc'] = 'Base64 Ed25519 public key eji atụ aro bundle signatures. Mepụta keypair site na <code>policy_bundle_tool.php --keygen</code>; private key na-anọdị na onye dere bundle ma ọ kwesịghị ibugharị ebe ọ bụla.';
$string['settings:policy_bundle_status'] = 'Sync ikpeazụ';
$string['settings:policy_bundle_applied_version'] = 'ụdị etinyere';
$string['task:policy_bundle_sync'] = '[[tutorshort]] signed policy bundle sync';
