$string['radar_report:privacy_note'] = 'Edeela data ndị mmụta niile dị na akụkọ a n\'amaghị aha. Ekesala ya n\'ihu ọha.';

$string['settings:hidden_categories'] = 'Ụdị nkuzi ezoro ezo';
$string['settings:hidden_categories_desc'] = 'Ndepụta aha ma ọ bụ ID nke ụdị nkuzi, nke e kewara site na rịkọm, ebe onye enyemaka na-ekwesịghị ịpụta. Ọmụmaatụ: "Mmepe nkuzi, 42". A na-ezokwa onye enyemaka na-akpaghị aka mgbe ọnọdụ ndezi na-arụ ọrụ.';
$string['settings:provider_heading'] = 'Onye na-enye AI na mkparịta ụka';
$string['settings:provider_heading_desc'] = 'Hazie ikpo okwu AI, ihe nlereanya, na omume n\'ime mkparịta ụka.';
$string['settings:claude_temperature_allow_prefixes'] = 'Ihe nlereanya Claude nke na-akwado paramita temperature';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Otu mmalite aha ihe nlereanya n\'ahịrị ọ bụla. Ihe nlereanya Anthropic bụ́ ndị aha ha na-amalite na otu n\'ime ndị a ka na-anabata paramita nnyocha <code>temperature</code>. Maka ihe nlereanya Claude ọ bụla na-adabaghị na mmalite ọ bụla, a na-ahapụ temperature (ihe nlereanya echiche site na Opus 4.7 gaa n\'ihu na-ajụ ya site na njehie HTTP 400). Hapụ ya nkịtị iji jiri uru ndabara nke na-eso mgbakwunye ahụ.';
$string['settings:max_tokens'] = 'Ogologo azịza kachasị (tokens)';
$string['settings:max_tokens_desc'] = 'Ọnụọgụgụ tokens kachasị maka azịza AI ọ bụla. Uru dị ala na-enye azịza dị mkpirikpi ma ngwa ngwa. 512 = ihe dịka ahịrịokwu 2-3, 1024 = ihe dịka paragraf 1-2, 2048 = nkọwa ndị toro ogologo. Tinye 0 ka enweghị oke (uru ndabara nke onye na-enye ga-arụ ọrụ).';
$string['settings:profile_update_interval'] = 'Oge nmelite profaịlụ nwa akwụkwọ';
$string['settings:profile_update_interval_desc'] = 'Mgbe ọnụọgụgụ ozi a si n\'aka nwa akwụkwọ n\'ime nkuzi gasịrị, onye enyemaka na-ewu (ma ọ bụ na-emelite) profaịlụ mmụta nke na-achịkọta ike, adịghị ike, ụdị mmụta, na ihe mmasị. A na-etinye profaịlụ a n\'ime ntuziaka sistemu maka azịza ahaziri onwe. Tinye 0 ka i mechie ya. Ndabara: 10.';
$string['settings:enable_thinking'] = 'Echiche gbasaa (Claude naanị)';
$string['settings:enable_thinking_desc'] = 'Ọ na-agbanye echiche nke na-adaba maka ihe nlereanya Claude. Claude n\'onwe ya na-ekpebi mgbe na ogo ọ ga-eche echiche banyere nsogbu tupu ọ zaa. Ọ na-eme ka izi ezi dịkwuo mma n\'ajụjụ siri ike, mana ọ na-abawanye ojiji tokens na igbu oge. A naghị egosi ụmụ akwụkwọ ihe dị n\'ime echiche ahụ. Ndị ọzọ na-enye na-eleghara ntọala a anya.';
$string['settings:rag_sources_heading'] = 'Ebe sitere ọdịnaya RAG';
$string['settings:rag_sources_heading_desc'] = 'Họrọ ụdị ọdịnaya nkuzi nke onye nhazi ndepụta RAG ga-ewepụta ederede na ha. Ihe ngosi ọnọdụ dị na <a href="{$a}">ibe nlekọta RAG</a> na-egosi ma onye nwepụta ọ bụla nwere ihe ọ chọrọ ka ọ rụọ ọrụ (dịka ngwá ọrụ pdftotext ma ọ bụ ndepụta ikike Cloudflare).';
$string['settings:rag_extract_pdf'] = 'Depụta faịlụ PDF (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Ọ na-ewepụta ederede site na faịlụ PDF ebugoro site na ngwá ọrụ <code>pdftotext</code> (poppler). A na-achọpụta ụzọ ngwá ọrụ ahụ na-akpaghị aka; gosi ya n\'okpuru ma ọ dị mkpa.';
$string['settings:rag_pdftotext_path'] = 'Ụzọ ngwá ọrụ pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Hapụ ya nkịtị maka nchọpụta na-akpaghị aka (a na-enyocha <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> na <code>which pdftotext</code>). Dejupụta ya naanị ma ọ bụrụ na nwụnye gị dị ebe ọzọ.';
$string['settings:rag_extract_docx'] = 'Depụta faịlụ DOCX (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Ọ na-ewepụta ederede site na akwụkwọ Word ebugoro site na ZipArchive nke PHP. Achọghị ihe ndabere ọ bụla si n\'èzí.';
$string['settings:rag_extract_pptx'] = 'Depụta faịlụ PPTX (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Ọ na-ewepụta ederede site na ihe ngosi PowerPoint ọgbara ọhụrụ ebugoro site na ZipArchive nke PHP. Ọ na-agafe XML nke slaịdị na ndetu onye na-ekwu okwu n\'usoro slaịdị; achọghị ihe ndabere ọ bụla si n\'èzí. A naghị akwado faịlụ binary <code>.ppt</code> ochie — chekwaa ihe ngosi ndị ahụ ọzọ dị ka <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'Depụta ọdịnaya H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Ọ na-agafe JSON nke ọdịnaya H5P ma na-edepụta ubi niile nwere ederede (ajụjụ, azịza, nzaghachi, nkọwa). Metadata nke ụdị ọdịnaya H5P sara mbara; n\'ọnọdụ oke, a na-atụ anya ụfọdụ ndakọrịta na-ezighị ezi.';
$string['settings:rag_extract_scorm'] = 'Depụta ngwugwu SCORM (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Ọ na-emeghe ngwugwu SCORM ma na-edepụta <code>imsmanifest.xml</code>, faịlụ <code>.html</code> niile, na eriri ọdịnaya Articulate Storyline. <strong>Emechiri ya na ndabara</strong>, n\'ihi na nhazi SCORM nwere ike ịdị oke ọnụ. <code>rag_scorm_max_mb</code> na-ekpebi nha ngwugwu kachasị.';
$string['settings:rag_scorm_max_mb'] = 'Nha ngwugwu SCORM kachasị a ga-edepụta (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Ọ na-agafe ngwugwu SCORM ndị buru ibu karịa uru a ka e zere iji ebe nchekwa n\'ụba.';
$string['settings:rag_fetch_transcripts'] = 'Bute ederede okwu maka vidiyo na ọdịnaya mmekọrịta etinyere';
$string['settings:rag_fetch_transcripts_desc'] = 'Ọ na-enyocha ọdịnaya mod_page na mod_book maka iframe etinyere (Synthesia, YouTube, Articulate, Genially) ma na-ebute adreesị ederede okwu nke so ntinye ọ bụla (ọ na-achọ n\'elu na n\'okpuru etiti ahụ). Ọ chọrọ njikọ HTTPS na-apụ apụ site na sava a gaa na onye nnabata ederede okwu. <strong>Emechiri ya na ndabara</strong>; gbanye ya mgbe onye na-enye ederede okwu tinyere sava a n\'ime ndepụta ikike ha (dịka site na iwu Cloudflare dabere na IP).';
$string['settings:rag_iframe_host_patterns'] = 'Ụkpụrụ onye nnabata iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Otu okwu nkịtị n\'ahịrị ọ bụla, nke a na-eji dakọrịta na àgwà <code>src</code> nke iframe. A na-ewere etiti ọ bụla dakọrọ dị ka ntinye mmekọrịta nke a ga-ejikọ ederede okwu ya ma depụta ya. Ahịrị ndị na-amalite na <code>#</code> bụ nkọwa.';
$string['settings:rag_transcript_url_pattern'] = 'Ụkpụrụ adreesị ederede okwu';
$string['settings:rag_transcript_url_pattern_desc'] = 'Okwu nkịtị nke dakọrọ na adreesị njikọ ederede okwu. Maka iframe ọ bụla a chọpụtara, onye nhazi ndepụta na-ahọrọ njikọ dakọrọ kacha nso (n\'elu ma ọ bụ n\'okpuru ya) ma jikọọ ha abụọ. Hapụ ya nkịtị iji mechie njikọ ederede okwu.';
$string['settings:performance_heading'] = 'Arụmọrụ';
$string['settings:performance_heading_desc'] = 'Ọ na-achịkwa ogo ọdịnaya nkuzi a na-etinye n\'ime ntuziaka AI. Uru dị ala pụtara azịza ngwa ngwa mana ọnọdụ nta maka AI.';
$string['settings:max_content_per_resource'] = 'Ọdịnaya kachasị maka akụ ọ bụla (mkpụrụedemede)';
$string['settings:max_content_per_resource_desc'] = 'Ọnụọgụgụ mkpụrụedemede ọdịnaya kachasị a na-ewepụta site na ibe ma ọ bụ isiakwụkwọ ọ bụla. Uru dị ala na-ebelata nha ntuziaka ma na-eme ka azịza dị ọsọ.';
$string['settings:max_total_content'] = 'Ọdịnaya niile kachasị (mkpụrụedemede)';
$string['settings:max_total_content_desc'] = 'Ọnụọgụgụ mkpụrụedemede ọdịnaya nkuzi niile kachasị nke a na-etinye n\'ime ntuziaka sistemu. Uru dị ala na-ebelata nha ntuziaka ma na-eme ka azịza dị ọsọ.';
$string['settings:spend_guard_heading'] = 'Nchekwa mmefu na onye nkwalite';
$string['settings:spend_guard_heading_desc'] = 'Tọọ oke mmefu LLM maka oge ọ bụla. Mgbe e rutere oke, [[tutorshort]] na-akwụsịtụ arịrịọ ma ọ bụ na-agbanwe gaa n\'onye na-enye dị ọnụ ala site n\'agbụ nkwado gị. Lee <a href="{$a}">ibe ọnụahịa tokens</a> maka ọnọdụ mmefu ugbu a na ndụmọdụ onye nkwalite.';
$string['settings:spend_cap_period'] = 'Oge oke mmefu';
$string['settings:spend_cap_period_desc'] = 'Ugboro ole a na-atọgharị oke mmefu. Ọ na-eso kalenda: nke ọnwa na-amalite na ụbọchị 1, nke izu na Mọnde, na nke ụbọchị n\'etiti abalị.';
$string['settings:spend_cap_site'] = 'Oke mmefu maka saịtị dum (USD)';
$string['settings:spend_cap_site_desc'] = 'Oke mkpokọta na USD maka nkuzi na ike niile n\'oge ugbu a. <code>0</code> = enweghị oke. Oke ike ọ bụla n\'okpuru na-eburu ụzọ mgbe a tọrọ ha.';
$string['settings:spend_cap_chat'] = 'Oke mkparịta ụka (USD)';
$string['settings:spend_cap_chat_desc'] = 'Oke maka mkparịta ụka na ule ụmụ akwụkwọ naanị. <code>0</code> = a na-eji oke saịtị dum.';
$string['settings:spend_cap_voice'] = 'Oke olu (USD)';
$string['settings:spend_cap_voice_desc'] = 'Oke maka olu (Realtime + TTS + STT). Olu na-abụkarị mmefu kacha ukwuu — machie ya mbụ.';
$string['settings:spend_cap_rag'] = 'Oke RAG (USD)';
$string['settings:spend_cap_rag_desc'] = 'Oke maka oku embedding nke na-eme n\'oge ndepụta nkuzi.';
$string['settings:spend_cap_analytics'] = 'Oke nyocha (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Oke maka ajụjụ Learning Radar nke ndị nlekọta.';
$string['settings:spend_failover_chain'] = 'Agbụ nkwado';
$string['settings:spend_failover_chain_desc'] = 'Mgbe e rutere oke, [[tutorshort]] na-anwale ndị na-enye ndị a n\'usoro. Otu ntinye n\'ahịrị ọ bụla, n\'ụdị <code>capability:label</code>. Akara na-ezo aka na ntinye dị na Ndị na-enye ntụnyere (maka <code>chat</code> / <code>analytics</code>) ma ọ bụ Ndị na-enye olu (maka <code>voice</code>). Ahịrị ndị na-amalite na <code>#</code> bụ nkọwa. Ọmụmaatụ:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Ịgbanwe gaa nkwado n\'oku ọ bụla (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Mgbe agbanyere ya, oku mkparịta ụka ọ bụla na-ekechi onye na-enye isi n\'ime mkpuchi agbụ nkwado. Ọ bụrụ na oge gwụrụ n\'oku ma ọ bụ njehie 5xx mere, [[tutorshort]] na-agbanwe gaa na ntinye na-esote na <strong>agbụ nkwado</strong> dị n\'elu ma na-emeghe sekit nkeji 15 maka onye na-enye dara. Mgbanwe ọ bụla na-ede ahịrị nyocha (<code>failover_fallthrough</code>); mgbe ị gbanyere ya, lee Nlekọta -> [[tutorshort]] -> Ndekọ nyocha iji kwado na agbụ ahụ na-arụ ọrụ. Emechiri ya na ndabara; gbanye ya naanị mgbe e nyochara agbụ ahụ na mgbe ụlọ akwụkwọ gị kwadoro na nkwekọrịta nhazi data dị mkpa dị maka onye na-enye ọ bụla n\'agbụ ahụ.';
$string['settings:failover_timeout_chat'] = 'Nkwado: oge ichere mkparịta ụka (sekọnd)';
$string['settings:failover_timeout_chat_desc'] = 'Oge a ga-eche maka token mbụ site n\'aka onye na-enye mkparịta ụka tupu ịgbanwe. Ndabara sekọnd 8. Uru dị ala na-apụ n\'ebe ndị na-enye na-egbu oge ngwa ngwa, mana ọ na-ebute ọtụtụ mkpu ụgha n\'arịrịọ ndị na-egbu oge nwa oge; uru dị elu na-ejide agbụ ahụ n\'aka onye na-enye isi ogologo oge. A na-atụle ya naanị mgbe <strong>ịgbanwe gaa nkwado n\'oku ọ bụla</strong> na-arụ ọrụ.';
$string['settings:spend_notify_emails'] = 'Ndị na-anata ọkwa mmefu';
$string['settings:spend_notify_emails_desc'] = 'Adreesị email nke e kewara site na rịkọm nke a ga-agwa na 80%, 95%, na 100% nke oke. Hapụ ya nkịtị iji gwa ndị nlekọta saịtị niile.';
$string['settings:opt_cost_weight'] = 'Onye nkwalite: ibu ọnụahịa';
$string['settings:opt_cost_weight_desc'] = 'Ogo onye nkwalite ji ọnụahịa kpọrọ ihe mgbe ọ na-ahazi ndị na-enye. 0.0 na-eleghara ọnụahịa anya, 1.0 na-akwalite dabere na ọnụahịa naanị. A na-atụle ya na ibu ogo.';
$string['settings:opt_quality_weight'] = 'Onye nkwalite: ibu ogo';
$string['settings:opt_quality_weight_desc'] = 'Ogo onye nkwalite ji afọ ojuju nwa akwụkwọ (ọnụọgụ ntule dị mma) kpọrọ ihe mgbe ọ na-ahazi ndị na-enye. 0.0 na-eleghara ogo anya.';
$string['settings:inactivity_reminder_enabled'] = 'Ncheta maka enweghị mmega';
$string['settings:inactivity_reminder_enabled_desc'] = 'Ọ na-eziga email kwa izu nye ụmụ akwụkwọ ndị na-emeghebeghị nkuzi ha ruo ọnụọgụgụ ụbọchị e tọrọ.';
$string['settings:inactivity_threshold_days'] = 'Oke enweghị mmega (ụbọchị)';
$string['settings:inactivity_threshold_days_desc'] = 'Ụbọchị ole nke enweghị mmega tupu e ziga email ncheta.';
$string['settings:voice_providers_heading'] = 'Ndị na-enye olu (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Hazie otu onye ma ọ bụ karịa na-enye API olu. Ntọala ndị a nwere onwe ha site n\'onye na-enye mkparịta ụka dị n\'elu na onye na-enye embedding maka RAG — olu nwere ndepụta ndị na-enye nke ya, n\'ihi na ugbu a naanị OpenAI na xAI na-enye ebe njedebe Realtime dabere na WebSocket, TTS, na STT. Jiri ndepụta ndị dị n\'okpuru ka ị họrọ onye na-enye edebanyere aha ga-elekọta ike ọ bụla. Ọ bụrụ na akọwaghị ahịrị ọ bụla, omume igodo otu ochie na-arụ ọrụ (igodo API Realtime dị n\'elu ma ọ bụ igodo OpenAI isi). Saịtị nke na-eji Together AI / Anthropic / DeepSeek / Gemini / Mistral maka mkparịta ụka ga-ahazi ma ọ dịkarịa ala otu ahịrị ebe a ka olu rụọ ọrụ.';
$string['settings:voice_active_realtime'] = 'Onye na-enye Realtime na-arụ ọrụ';
$string['settings:voice_active_realtime_desc'] = 'Onye na-enye olu ahaziri ole ga-elekọta oge nnọkọ onye nnọchite anya olu Realtime.';
$string['settings:voice_active_tts'] = 'Onye na-enye TTS na-arụ ọrụ';
$string['settings:voice_active_tts_desc'] = 'Onye na-enye olu ahaziri ole ga-agụ azịza AI n\'olu dara ụda.';
$string['settings:voice_active_stt'] = 'Onye na-enye STT na-arụ ọrụ';
$string['settings:voice_active_stt_desc'] = 'Onye na-enye ole ga-agbanwe okwu ụmụ akwụkwọ ka ọ bụrụ ederede. Hapụ ya nkịtị ka a bulie sava Whisper nke gị ụzọ ma ọ bụrụ na ahaziri ya n\'okpuru, mgbe ahụ ahịrị mbụ nke ndị na-enye olu ma ọ bụ igodo ochie.';
$string['settings:stt_selfhosted_enabled'] = 'Gbanye ederede okwu na sava nke gị';
$string['settings:stt_selfhosted_enabled_desc'] = 'Ọ na-eji sava Whisper nke gị dị n\'okpuru dị ka ụzọ ntụgharị okwu gaa ederede maka ntinye olu na Soapbox. Ọ chọrọ adreesị sava n\'okpuru. Mgbe emechiri ya, ederede okwu na-alaghachi n\'ụzọ e nyefere (OpenAI Whisper) ma ọ bụ ụzọ ihe nchọgharị, ọ bụrụgodụ na atọrọ adreesị ahụ.';
$string['settings:stt_selfhosted_warm'] = 'Kpoo ọkụ mgbe ndekọ Soapbox na-amalite';
$string['settings:stt_selfhosted_warm_desc'] = 'Mgbe agbanyere ya, ịmalite ndekọ Soapbox na-eziga arịrịọ "nkpo ọkụ" dị mfe (ka o kwere mee) na sava ederede okwu nke gị, ka onye nnabata nke na-ebelata ruo efu (dịka Cloud Run) nwee ike ịmalite mgbe nwa akwụkwọ ka na-edekọ — otu a, igbu oge nke mmalite oyi na-anọ n\'ezoro ezo n\'ebe ederede okwu na-arụ ọrụ mgbe nnyefe. Ọ nweghị mmetụta ma ọ bụrụ na atọghị adreesị sava nke gị n\'elu. Emechiri ya na ndabara.';
$string['settings:voice_tab_enabled'] = 'Gbanye taabụ Olu';
$string['settings:voice_tab_enabled_desc'] = 'Ọ na-egosi taabụ Olu na ogwe nchọgharị dị n\'okpuru. Mgbe emechiri ya, ụmụ akwụkwọ na-ahụ naanị taabụ Mkparịta ụka na Ndetu. Ike olu (omume mkparịta ụka, omume mkpọpụta) ka na-erute site na ihe mmalite mkparịta ụka ma ọ bụrụ na agbanyere ha n\'onwe ha.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Omume ngosipụta ọnụ: otu a ga-esi dee ndekọ na ụkpụrụ a ga-eji nye ha akara. Gbanye Soapbox maka nkuzi ọ bụla site na mgba Soapbox dị na ngalaba Nkuzi.';
$string['settings:soapbox_max_seconds'] = 'Ogologo ndekọ Soapbox kachasị (sekọnd)';
$string['settings:soapbox_max_seconds_desc'] = 'Oke elu zuru oke maka ogologo ndekọ n\'ọrụ ọ bụla. Ndị nkuzi nwere ike ịtọ oke dị mkpirikpi. Ndabara 720 (nkeji 12).';
$string['settings:soapbox_max_recordings'] = 'Ndekọ Soapbox kachasị maka nwa akwụkwọ na ọrụ ọ bụla';
$string['settings:soapbox_max_recordings_desc'] = 'Oke elu zuru oke maka ọnụọgụgụ ndekọ nwa akwụkwọ nwere ike ime maka otu ọrụ, n\'agbanyeghị ntọala ọnụọgụgụ mgbalị maka ọrụ ọ bụla. Ndabara 3.';
$string['settings:soapbox_retention_days'] = 'Oge nchekwa ndekọ Soapbox (ụbọchị)';
$string['settings:soapbox_retention_days_desc'] = 'Oge a na-echekwa ndekọ tupu ehichapụ ya na-akpaghị aka; a na-echekwa ederede okwu, akara, na nzaghachi. A na-amachi ya na ụbọchị 1–28. Ka ọ dịkwuo mkpirikpi, ka ọ dịkwuo mma maka ibelata data. Ndabara 7.';
$string['settings:soapbox_video_quality'] = 'Ogo vidiyo Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Nkọwapụta na ọnụọgụ bit nke ndekọ. Nke a bụ ihe kacha kpata ọnụahịa na ọsọ njikọ; onye na-ekwu okwu nke e sere n\'etiti ka na-apụta nke ọma na ogo nkịtị. Ogo dị ala dabara maka njikọ na-adịghị ike; ogo dị elu naanị mgbe nkọwa anya dị mkpa.';
$string['settings:soapbox_storage_bucket'] = 'Bọket nchekwa Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'Bọket S3 maka ndekọ. Ndabara: bọket ebe nchekwa a na-ekekọrịta.';
$string['settings:soapbox_storage_region'] = 'Mpaghara nchekwa Soapbox';
$string['settings:soapbox_storage_region_desc'] = 'Mpaghara AWS nke bọket ahụ, dịka us-east-1.';
$string['settings:soapbox_storage_prefix'] = 'Mmalite igodo nchekwa Soapbox';
$string['settings:soapbox_storage_prefix_desc'] = 'Mmalite igodo n\'ime bọket ahụ. A na-echekwa ndekọ n\'okpuru ụzọ a, ka iwu usoro ndụ wee nwee ike lekwasị ha anya.';
$string['settings:soapbox_storage_key'] = 'ID igodo nnweta nchekwa Soapbox';
$string['settings:soapbox_storage_key_desc'] = 'ID igodo nnweta nke onye IAM nke a machiri na PutObject/GetObject/DeleteObject n\'elu mmalite dị n\'elu.';
$string['settings:soapbox_storage_secret'] = 'Igodo nnweta nzuzo nke nchekwa Soapbox';
$string['settings:soapbox_storage_secret_desc'] = 'Igodo nnweta nzuzo nke dakọrọ na ID igodo nnweta dị n\'elu.';
$string['settings:survey_heading'] = 'Nnyocha ụmụ akwụkwọ';
$string['settings:survey_heading_desc'] = 'Hazie nnyocha ahụmịhe nwa akwụkwọ n\'ime mkparịta ụka. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">Dezie ajụjụ nnyocha &rarr;</a>';
$string['settings:survey_enabled'] = 'Gbanye nnyocha';
$string['settings:survey_enabled_desc'] = 'Mgbe agbanyere ya, a ga-agwa ụmụ akwụkwọ ka ha dejupụta nnyocha banyere ahụmịhe ha na onye nkuzi AI.';
$string['settings:survey_trigger_messages'] = 'Gosi mgbe ozi N gasịrị';
$string['settings:survey_trigger_messages_desc'] = 'Ọ na-egosi òkù nnyocha mgbe nwa akwụkwọ zigara ọnụọgụgụ ozi a n\'ime nkuzi. Tinye 0 ka egosi ya naanị mgbe e ji aka kpalie ya.';
$string['settings:survey_frequency'] = 'Ugboro nnyocha maka onye ọrụ ọ bụla';
$string['settings:survey_frequency_desc'] = 'Ugboro ole a nwere ike ịkpọ nwa akwụkwọ ka o dejupụta nnyocha na nkuzi ọ bụla.';
$string['settings:rubric_heading'] = 'Ụkpụrụ omume';
$string['settings:rubric_heading_desc'] = 'Hazie ụkpụrụ inye akara maka oge omume mkparịta ụka na mkpọpụta. Na njedebe oge omume, ụmụ akwụkwọ na-anata akara na nzaghachi nke AI mepụtara. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">Dezie ụkpụrụ &rarr;</a>';
$string['settings:practice_scoring_enabled'] = 'Gbanye inye akara omume';
$string['settings:practice_scoring_enabled_desc'] = 'Mgbe agbanyere ya, mgbe oge omume mkparịta ụka na mkpọpụta gasịrị, ụmụ akwụkwọ na-anata kaadị akara nwere ntule maka ụkpụrụ ọ bụla na nzaghachi.';
$string['settings:usertesting_heading'] = 'Nnwale mfe ojiji';
$string['settings:usertesting_heading_desc'] = 'Nnwale mfe ojiji n\'ime ngwá ahụ nwere ntule dabere na ọrụ. Ụmụ akwụkwọ na-emecha ọrụ n\'ime onye enyemaka ma na-enye ahụmịhe ha akara. Nsonaazụ na-apụta na dashboard nyocha.';
$string['settings:usertesting_enabled'] = 'Gbanye nnwale mfe ojiji';
$string['settings:usertesting_enabled_desc'] = 'Ọ na-egosi njikọ "Nnwale mfe ojiji" n\'okpuru ngwá ahụ. Mgbe agbanyere ya, ụmụ akwụkwọ nwere ike iru ọrụ nnwale.';
$string['settings:usertesting_external_url'] = 'Adreesị fọm si n\'èzí (ụdị C)';
$string['settings:usertesting_external_url_desc'] = 'Nhọrọ: adreesị fọm si n\'èzí (dịka Google Forms ma ọ bụ Typeform). Jiri ihe nnọchi: {{userid}}, {{courseid}}, {{messages}}, {{session_minutes}}. Ọ bụrụ na atọrọ ya, ịpị "Nnwale mfe ojiji" na-emeghe adreesị a ebe e dejupụtara ọnọdụ. Hapụ ya nkịtị iji jiri naanị panel nnwale dị n\'ime ngwá ahụ.';
$string['settings:footer_links_heading'] = 'Njikọ dị n\'okpuru';
$string['settings:footer_links_heading_desc'] = 'Hazie njikọ ndị na-apụta n\'okpuru onye enyemaka: njikọ nhọrọ gaa na ndepụta nkuzi n\'okpuru njikọ nzaghachi, na okwu njikọ nzaghachi na panel ya.';
$string['settings:footer_courses_text'] = 'Ederede njikọ nkuzi';
$string['settings:footer_courses_text_desc'] = 'Ederede njikọ nke na-apụta n\'okpuru njikọ nzaghachi. Hapụ ya nkịtị iji zoo njikọ ahụ kpamkpam.';
$string['settings:footer_courses_url'] = 'Adreesị njikọ nkuzi';
$string['settings:footer_courses_url_desc'] = 'Ebe njikọ nkuzi na-eje (ọ na-emeghe na taabụ ọhụrụ). A na-ezo njikọ ahụ ma ọ bụrụ na ubi a bụ nkịtị.';
$string['settings:feedback_link_label'] = 'Akara njikọ nzaghachi';
$string['settings:feedback_link_label_desc'] = 'Ọ na-anọchi ederede njikọ nzaghachi dị n\'okpuru, dịka "Ziga echiche gbasara [[tutorshort]] nye ndị otu IT". Hapụ ya nkịtị iji jiri akara ndabara a sụgharịrị "Nzaghachi".';
$string['settings:feedback_panel_intro'] = 'Mmalite panel nzaghachi';
$string['settings:feedback_panel_intro_desc'] = 'Ahịrị mmalite nke na-apụta n\'elu panel nzaghachi. Ọ na-akọwa ebe echiche na-eje. Hapụ ya nkịtị ka ahịrị mmalite ghara ịdị.';
$string['settings:quiz_provider'] = 'Onye na-enye onye enyemaka ule';
$string['settings:quiz_provider_desc'] = 'ID onye na-enye (dịka <code>claude</code> ma ọ bụ <code>openai</code>) maka imepụta ule. Ọ ga-adaba na otu ahịrị dị na Ndị na-enye ntụnyere. Hapụ ya nkịtị iji jiri onye na-enye mkparịta ụka.';
$string['settings:quiz_model'] = 'Ihe nlereanya onye enyemaka ule';
$string['settings:quiz_model_desc'] = 'Aha ihe nlereanya maka imepụta ule, dịka <code>claude-haiku-4-5</code>. A ga-edejupụta ubi a na onye na-enye ka mgbanwe ahụ wee rụọ ọrụ.';
$string['settings:branding_heading'] = 'Njirimara akara';
$string['settings:branding_heading_desc'] = 'Hazie aha na ọdịdị onye enyemaka.';
$string['settings:institution_short_name'] = 'Aha mkpirikpi nke ụlọ akwụkwọ';
$string['settings:institution_short_name_desc'] = 'Aha mkpirikpi nke ụlọ akwụkwọ maka ihe interface nwere obere ohere (dịka "State U").';
$string['settings:display_name'] = 'Aha ngosi nke onye enyemaka';
$string['settings:display_name_desc'] = 'Aha zuru ezu nke onye enyemaka AI, dị ka ọ na-apụta na ekele na na ihuenyo nnabata (dịka "Onye Enyemaka Mmụta Ịntanetị").';
$string['settings:short_name'] = 'Aha mkpirikpi nke onye enyemaka';
$string['settings:short_name_desc'] = 'Aha mkpirikpi a na-eji na ogwe aha na ihe interface nwere obere ohere (dịka "Onye Enyemaka").';
$string['settings:welcome_message'] = 'Ozi ihuenyo nnabata';
$string['settings:welcome_message_desc'] = 'Ozi nke na-apụta n\'ihuenyo nnabata na nleta mbụ. Jiri <code>{{firstname}}</code> maka aha nwa akwụkwọ na <code>{{coursename}}</code> maka aha nkuzi. Hapụ ya nkịtị maka ederede ndabara.';
$string['settings:chat_greeting'] = 'Ekele mkparịta ụka';
$string['settings:chat_greeting_desc'] = 'Ozi ekele nke na-apụta mgbe e mepere windo mkparịta ụka. Jiri <code>{{firstname}}</code> maka aha nwa akwụkwọ na <code>{{coursename}}</code> maka aha nkuzi. Hapụ ya nkịtị maka ederede ndabara.';
$string['settings:customavatars'] = 'Avata ahaziri onwe';
$string['settings:customavatars_desc'] = 'Bugoo foto PNG ma ọ bụ SVG nwere akụkụ anọ nhata ebe a iji tinye ha na ndepụta avata dị n\'elu. Faịlụ ọ bụla ebugoro na-abụ nhọrọ ndabara (nwere mmalite "Custom:"). Hichapụ faịlụ site na ndepụta a iji wepụ ya na ndepụta na-adaba. Ndụmọdụ: PNG 256×256 na-apụta nke ọma n\'ihuenyo Retina.';
$string['settings:anomaly_digest_heading'] = 'Learning Radar — nchịkọta ihe na-adịghị mma';
$string['settings:anomaly_digest_heading_desc'] = 'Nyocha kwa ụbọchị nke na-atụnyere oge na-agagharị nke ntule ọjọọ, mmefu tokens, na akara ezi omume. Mgbe ihe ngosi gafere oke e tọrọ, a na-eziga nchịkọta na ọwa ndị ahaziri. Maka akụkọ ahaziri maka ajụjụ ọ bụla, jiri panel Nhazi oge dị n\'ibe nyocha [[tutorshort]].';
$string['settings:anomaly_digest_enabled'] = 'Gbanye nchịkọta ihe na-adịghị mma';
$string['settings:anomaly_digest_enabled_desc'] = 'Ọ na-arụ ọrụ kwa ụbọchị nke nchịkọta ihe na-adịghị mma. Ọ dị jụụ na ndabara — ọ na-arụ ọrụ naanị mgbe ihe ngosi gafere oke.';
$string['settings:anomaly_digest_threshold_pct'] = 'Oke ọkwa (%)';
$string['settings:anomaly_digest_threshold_pct_desc'] = 'Mgbanwe pasent n\'etiti oge nso na oge gara aga nke na-akpalite ọkwa. Ndabara: 50.';
$string['settings:anomaly_digest_recipient_email'] = 'Adreesị email onye nnata';
$string['settings:anomaly_digest_recipient_email_desc'] = 'Adreesị email nke na-anata nchịkọta ihe na-adịghị mma. Hapụ ya nkịtị iji jiri adreesị onye nlekọta saịtị.';
$string['settings:anomaly_digest_slack_webhook'] = 'Adreesị webhook na-abata nke Slack';
$string['settings:anomaly_digest_slack_webhook_desc'] = 'Adreesị webhook na-abata nke Slack nke nhọrọ. A na-ebipụta nchịkọta ahụ dị ka ozi blọk Slack.';
$string['settings:anomaly_digest_teams_webhook'] = 'Adreesị webhook na-abata nke Microsoft Teams';
$string['settings:anomaly_digest_teams_webhook_desc'] = 'Adreesị webhook na-abata nke Teams nke nhọrọ. A na-ebipụta nchịkọta ahụ dị ka kaadị njikọ Office 365.';

$string['settings:embed_query_model'] = 'Ụdị mgbakwunye ajụjụ (dị elu)';
$string['settings:embed_query_model_desc'] = 'Hapụ ya efu ma ọ bụghị na ị maara nke ọma na ịchọrọ ya. Na mkpọtụ, a na-etinye ajụjụ na ọdịnaya kọọsụ site n\'otu ụdị, nke bụ naanị nhọrọ dị nchebe mgbe niile: enweghị ike itụnyere vektọ sitere n\'ụdị dị iche iche, na ịgwakọta ha na-enye nsonaazụ nke yiri ka ọ bụ eziokwu mana enweghị uche, kama igosi njehie. Debe nke a naanị mgbe ụdị abụọ ahụ na-ekere oghere mgbakwunye otu — ugbu a ezinụlọ Voyage 4 (voyage-4-large, voyage-4, voyage-4-lite, voyage-4-nano), nke edepụtara na ha nwere ike dochie ibe ha. Uru ya bụ na ị nwere ike gbanwee ụdị ajụjụ ma emechaa n\'enweghị itinye katalọgụ kọọsụ gị niile ọzọ. Ọ bụrụ na ụdị ndị ahụ apụta na enweghị ike itụnyere ha, nweta ga-edekọ ịdọ aka ná ntị ma ghara iweghachi ihe ọ bụla maka kọọsụ ahụ kama iweghachi akụkụ na-ezighị ezi.';
$string['settings:embed_dtype'] = 'Nkenke vektọ echekwara';
$string['settings:embed_dtype_desc'] = 'Oghere ole ka vektọ ọ bụla echekwara na-ewe. Nkenke dị ala na-echekwa nnukwu oghere diski mana ọ na-ebelata izi ezi nweta ntakịrị. <strong>Ịgbanwe nke a chọrọ ndenye ọzọ zuru ezu</strong> — enweghị ike ịgụ ụdị ndị ahụ n\'ọnọdụ ibe ha, na kọọsụ ọ bụla echekwara n\'ụdị ochie ka a ga-agafere (na ịdọ aka ná ntị na ndekọ) ruo mgbe edenyere ya ọzọ. Naanị ndị na-enye nkwado maka mbelata na-agbaso nke a; ndị ọzọ na-echekwa mgbe niile na nkenke zuru ezu.';
$string['settings:embed_dtype_float'] = 'Nkenke zuru ezu (nke kacha ukwuu, nke kacha ziri ezi)';
$string['settings:embed_dtype_int8'] = 'Nkenke ebelatara — ihe dị ka otu ụzọ n\'ụzọ anọ nke oghere';
$string['settings:embed_dtype_binary'] = 'Nke kacha nta — ihe dị ka otu ụzọ n\'ụzọ iri atọ nke oghere, izi ezi kacha ala';

