$string['quizlock:blocked'] = 'Onye enyemaka [[tutorshort]] adịghị adị ma ị nwere ule na-aga n\'ihu. Zipụ ma ọ bụ mechie mgbalị gị, ọ ga-adịkwa ọzọ.';
$string['quizlock:heading'] = 'Ọnọdụ ule';
$string['quizlock:enabled'] = 'Kpọchie onye enyemaka n\'oge ule Moodle';
$string['quizlock:enabled_desc'] = 'Ọ na-egbochi onye enyemaka n\'ebe niile — nkata, olu, kaadị mmụta, ule omume — mgbe onye mmụta nwere mgbalị ule na-aga n\'ihu. A na-enyocha ya na sava, ya mere imepe taabụ nke abụọ agaghị enyere aka ịgbanahụ ya. Onye nkuzi nwere ike wepụ otu ule site n\'ịtọ ọkwa enyemaka ya na Enyemaka zuru oke.';
$string['quizlock:window'] = 'Oge mgbalị ka dị irè (nkeji)';
$string['quizlock:window_desc'] = 'Ogologo oge mgbalị na ule na-enweghị oke oge ka a na-agụ dịka nke na-aga n\'ihu. Ule ndị nwere oke oge nke ha na-eji nke ha. Mgbalị ndị a hapụrụ na-anọgide na-aga n\'ihu ruo mgbe ebighị ebi, ya mere na-enweghị oke a otu ga-akpọchi onye mmụta ruo mgbe ebighị ebi. Ndabara: 180.';

$string['emergency:chat_stopped'] = '[[tutorshort]] kwụsịtụrụ ugbu a. Ihe ọmụmụ gị enweghị nsogbu, ọ bụghịkwa ihe i mere — biko nwaa ọzọ ma emesịa.';
$string['settings:money_nonnegative_invalid'] = 'Tinye ego ruru 0 ma ọ bụ karịa, na-eji ọnụọgụ abụọ kacha na-esote akara (dịka 25 ma ọ bụ 25.50).';

$string['chat:turn_failed'] = 'Enweghị ike ịmecha azịza a. Ọ dịghị ihe i mere kpatara ya — biko nwaa ọzọ.';
$string['settings:prompt_budget_mode'] = 'Ụdị mmefu ntuziaka sistemu';
$string['settings:prompt_budget_mode_desc'] = 'Otú e si ekpebi mmefu mkpụrụedemede nke ntuziaka sistemu. <strong>Site na ihe nlereanya nweta ya</strong> na-agbakọ ohere ihe nlereanya ahaziri na-enye n’ezie — mpio ihe gbara ya gburugburu, wepụ azịza echekwara na akụkọ mkparịta ụka — wee jiri ya, jiri oke iji hụ na mpio buru ibu adịghị enye ikike maka ntuziaka buru ibu. Nke a na-arụ ọrụ naanị mgbe mmefu mkpụrụedemede dị n’okpuru ka nọ na 36,000 nke ndabara: gbanwee ọnụọgụ ahụ, ọ ga-emeri, n’ụzọ abụọ, n’ihi na ọnụọgụ onye nchịkwa depụtara bụ mkpebi, ọ bụghị nkọwa. <strong>Edobere</strong> na-eji ọnụọgụ dị n’okpuru mgbe niile. Sava a na-akwado onwe ya kwesịrị ịtọ mpio ihe gbara sava ahụ gburugburu, nke na-ebute ụzọ karịa ihe niile dị ebe a.';
$string['settings:prompt_budget_mode_auto'] = 'Site na ihe nlereanya nweta ya (a na-akwado ya)';
$string['settings:prompt_budget_mode_fixed'] = 'Mmefu mkpụrụedemede edobere';

$string['quizlock:scope'] = 'Ebe mkpọchi ahụ ruru';
$string['quizlock:scope_course'] = 'Naanị nkuzi a (a na-akwado ya)';
$string['quizlock:scope_site'] = 'Nkuzi niile';
$string['quizlock:scope_desc'] = 'Ma mgbalị na-aga n\'ihu ọ ga-egbochi [[tutorshort]] naanị na nkuzi nwere ajụjụ ahụ, ka ọ bụ ebe niile. <strong>Naanị nkuzi a</strong> bụ ndabara, ọ bụkwa ihe ị chọrọ ihe fọrọ nke nta ka ọ bụrụ mgbe niile. Saịtị niile bụ omume ruo v7.2.4, o nwekwara nsogbu kwesịrị ịmara: mgbalị a hapụrụ ahapụ na-anọgide «na-aga n\'ihu» ruo mgbe ebighị ebi, ya mere otu ajụjụ echefuru n\'akụkọ nke onye mmụta na-agbanyụ onye enyemaka ahụ na nkuzi ọ bụla ọ na-amụ, n\'enweghị ihe ọ bụla na ihuenyo kọwara ya. Saịtị niile enweghị ike ime ihe dị ukwuu megide onye kpebisiri ike ịghọ aghụghọ, ebe ọ nwere ihe nchọgharị nke abụọ, ihe ọmụmụ na nchọta nke onye enyemaka ahụ bụkwa nke nkuzi naanị.';

$string['settings:prompt_budget_tuner_conflict'] = 'Ọrụ ndozi akpaaka nke mmefu ntuziaka akwụsịla agbanyere ka ụdị mmefu edobere ka e wepụta ya site n\'ihe nlereanya. Ha abụọ na-emegide onwe ha: ọrụ ahụ na-ede mmefu mkpụrụedemede, uru ọ bụla na-abụghị ndabara ka a na-agụ dịka nhọrọ ezubere, nke na-agbanyụ mmefu ewepụtara. Ọrụ ahụ na-akwụsị onwe ya ugbu a n\'ụdị a, ya mere ọ dịghị ihe a na-edegharị — mana gbanyụọ ya ka enweghị mgbagwoju anya.';

$string['settings:prompt_budget_no_window'] = 'Ụdị mmefu ego dị n\'elu ka edobere ka esite na ụdị ahụ nweta ya, mana ọ dịghị ihe esi na ya nweta: edobeghị ụdị nkata ahụ, edobeghịkwa windo ọnọdụ nke azụ, ya mere nweta ahụ na-alaghachi na mmefu mkpụrụedemede kwụsiri ike nke dị n\'okpuru. Debe ụdị nkata ahụ, ma ọ bụ debe windo ọnọdụ azụ site n\'aka gị, mgbe ahụ mee nnwale onwe azụ ọzọ ma chọpụta na nlele windo ọnọdụ gafere. Ruo mgbe ahụ, mmefu ahụ bụ ọnụọgụ dị n\'okpuru, n\'agbanyeghị ihe ụdị ahụ na-ekwu.';

$string['analytics_js:section'] = 'Ngalaba';
