$string['privacynotice:lastupdated'] = 'Emelitere ikpeazụ: {$a}. Ụdị 1.0.';
$string['privacynotice:whatis'] = 'Ihe [[tutorshort]] Bụ';
$string['privacynotice:whatis_p1'] = '[[tutorshort]] bụ onye nkuzi mmụta nke AI na-akwado nke [[uniname]], nke etinyere n\'ụfọdụ kọọsị. Mgbe [[tutorshort]] dị na kọọsị, ị ga-ahụ widget mkparịta ụka n\'ibe kọọsị. Ị nwere ike jụọ [[tutorshort]] ajụjụ gbasara ihe ọmụmụ, nweta ajụjụ mmega, hazie usoro mmụta gị, ma jiri atụmatụ olu ma ọ bụrụ na kọọsị gị gbanyere ha.';
$string['privacynotice:whatis_p2'] = '[[tutorshort]] adịghị na kọọsị niile nke [[uniname]]. Onye mmepe kọọsị na-ekpebi ma a ga-agbanye [[tutorshort]] na kọọsị.';
$string['privacynotice:collects'] = 'Ozi [[tutorshort]] Na-anakọta';
$string['privacynotice:collects_p1'] = 'Mgbe ị na-eji [[tutorshort]] na kọọsị, [[uniname]] na-edekọ ozi gị, azịza [[tutorshort]], kọọsị na oge nke mkparịta ọ bụla, ọkwa na nzaghachi ị nyere, atụmatụ mmụta gị na nhọrọ ihe ncheta ma ọ bụrụ na ị mepụta ha, avata ị họọrọla, na nchịkọta profaịlụ dị mkpirikpi nke [[tutorshort]] na-emepụta site na mkparịta ụka gị iji hazie nnọkọ ndị na-abịa.';
$string['privacynotice:collects_p2'] = '[[tutorshort]] na-anakọtakwa data teknụzụ nkịtị dị mkpa iji rụọ ọrụ ahụ: id onye ọrụ Moodle gị, adreesị IP, ụdị ihe nchọgharị, na akara oge. [[tutorshort]] anaghị edebe ndekọ nke ya maka aha gị zuru ezu, adreesị email (belụsọ ma ị wepụ onwe gị n\'email, nke na-echekwa adreesị nke mwepụ ahụ metụtara), adreesị ụlọ, nọmba ekwentị (belụsọ ma ị nye otu maka ihe ncheta), ozi ịkwụ ụgwọ, ma ọ bụ akara njirimara gọọmentị nyere; ebe aha gị pụtara n\'akụkụ data [[tutorshort]], a gụtara ya site n\'akaụntụ [[uniname]] gị dị adị kama [[tutorshort]] ichekwa ya.';
$string['privacynotice:uses'] = 'Otú E Ji Ozi Gị Eme Ihe';
