$string['privacynotice:uses_item2'] = 'Hazie azịza [[tutorshort]] maka gị.';
$string['privacynotice:uses_item3'] = 'Mee ka [[tutorshort]] n\'onwe ya ka mma, site n\'iji data e dere n\'amaghị aha na nke achịkọtara.';
