$string['settings:bench_default_samples'] = 'Prompt kwa ọsọ';
$string['settings:bench_default_samples_desc'] = 'Ole prompt ka benchmark e tinyere n\'ahịrị site na weebụ na-eziga. Prompt ọ bụla na-efu oku model abụọ dị ndụ — azịza ahụ na onye ikpe — ya mere nke a bụ igodo ọnụahịa. E jiri koodu kpachie ya na 50, nke bụ ma nha golden set ma ihe na-eme ka otu ọsọ nọrọ n\'ime oke ọsọ nke onye na-enye.';
$string['settings:bench_heading'] = 'Benchmark model';
$string['settings:bench_heading_desc'] = 'Otu ọsọ benchmark na-aza prompt 50 ma na-eme ka model onye ikpe nye azịza ọ bụla akara megide rubric, wee chekwaa otu ahịrị: nkezi rubric, ọnụahịa kwa oku, na oge ruo byte mbụ. A na-etinye ọsọ n\'ahịrị site n\'ibe registry model ma cron na-agba ha.';
$string['settings:bench_judge_model'] = 'Model onye ikpe';
$string['settings:bench_judge_model_desc'] = 'Model nke na-enye azịza akara. Ịgbanwe ya na-agbanwe ihe akara ọ bụla e were mgbe ahụ pụtara, nke bụ ihe kpatara na ọsọ ọ bụla na-edekọ onye ikpe o jiri na mwepụta plugin ọ gbara na ya.';
$string['settings:bench_judge_provider'] = 'Onye na-enye onye ikpe';
$string['settings:bench_judge_provider_desc'] = 'Onye na-enye maka model nke na-enye azịza akara. Debe ya n\'èzí ọdụ ndị na-asọ mpi: model ekwesịghị inye onwe ya akara.';
$string['settings:bench_min_quality_n'] = 'Ala ntụnyere (ihe e nyere akara)';
$string['settings:bench_min_quality_n_desc'] = 'Ọnụ ọgụgụ kacha nta nke ihe e nyere akara nke ọsọ echekwara nwere ike inwe ma ka nwee ike ịtụnyere ya na ọsọ ọzọ. A na-echekwa ma na-egosi ọsọ ndị dị n\'okpuru ala ahụ, e depụtara ha dị ka ntụaka naanị, ka ọsọ smoke nke prompt atọ ghara ịkarị nsonaazụ prompt iri ise. Hapụ ya na 0 iji jiri ndabara dị n\'ime koodu; ala nke 0 ga-emebi nchedo a.';
$string['settings:embed_input_type_asymmetric'] = 'Enweghị nhata ajụjụ/akwụkwọ (a na-akwado)';
$string['settings:embed_input_type_mode'] = 'Ụdị input embedding';
$string['settings:embed_input_type_mode_desc'] = 'Naanị maka embeddings nke Voyage. Voyage na-eweta ederede n\'ụzọ dị iche dabere na ma ọ bụ ajụjụ ka ọ bụ akwụkwọ. "Enweghị nhata" na-eziga input_type=query mgbe ị na-eweghachi na input_type=document mgbe ị na-edekọ. Nke ahụ bụ ihe onye na-eweta chọrọ, ọ bụkwa ya ka a tụrụ ka ọ kacha mma na mkpokọta a: iji nseta akwụkwọ n\'akụkụ ajụjụ furu isi 30.8 pasent nke recall ma tụfuo n\'ogo ogologo ajụjụ ọ bụla (2026-08-21, voyage-3.5, usoro yiri nke mmepụta). "Oghere nkekọrịta" na-eziga input_type=document n\'akụkụ abụọ; ọ na-eweghachi n\'ụzọ ọjọọ a pụrụ ịtụle ma dịrị naanị dị ka mkpuchi mbugharị, n\'ihi na nseta otu na-eme ka a gbanwee ihe nlereanya ajụjụ n\'enweghị itinyeghachi mkpokọta ahụ. Họrọ enweghị nhata ma ọ bụrụghị na ị nọ n\'etiti mbugharị. Ịgbanwe nke a achọghị ndekọghachi: naanị nseta n\'akụkụ ajụjụ na-agbanwe. Nke a ABỤGHỊ njikọ nlereanya enweghị nhata (idekọ site na nnukwu ihe nlereanya Voyage karịa nke ị na-eji ajụ) — nke ahụ bụ usoro dị iche nke enweghị ike ịmegharị ugboro abụọ na mkpokọta a, ntọala ihe nlereanya ajụjụ na-achịkwa ya, ọ bụghị ntọala a.';
$string['settings:embed_input_type_shared'] = 'Oghere nkekọrịta (mkpuchi mbugharị; nweghachi ọjọọ)';
$string['settings:embed_migration_heading'] = 'Mbufe model embedding';
$string['settings:embed_migration_heading_desc'] = 'Ịgbanwe model embedding ma ọ bụ obosara ya na-eme ka vector ọ bụla echekwara ghara irè: onye nweghachi na-ajụ inye query akara megide chunk sitere n\'ohere embedding dị iche, ya mere kọọsị anaghị eweghachi ihe ọ bụla kama iweghachi ihe na-adịghị mma. Ntọala ndị a na-akọwa model ị na-AGA NA YA. A na-emesịa embedding kọọsị otu otu site n\'ibe index RAG, na-ede vector ọhụrụ n\'akụkụ ndị ochie, na ntọala dị ndụ n\'elu na-anọgide na-eje ozi nweghachi ruo mgbe ị gbanwere ha n\'onwe gị.';
$string['settings:embed_migration_provider_inherit'] = 'Jiri onye na-enye ahaziri n\'elu';
$string['settings:embed_migration_target_apikey'] = 'Igodo API onye na-enye ebumnobi';
$string['settings:embed_migration_target_apikey_desc'] = 'Achọrọ ya naanị mgbe onye na-enye ebumnobi dị iche na nke ahaziri n\'elu. Ihe efu pụtara jiri igodo embedding dị adị.';
$string['settings:embed_migration_target_dimensions'] = 'Obosara embedding ebumnobi';
$string['settings:embed_migration_target_dimensions_desc'] = 'Obosara vector a ga-arịọ n\'oge mbufe. 0 pụtara obosara ọdịnala nke model. Voyage na-anabata 256, 512, 1024 na 2048; obosara nke model na-adịghị enye ka a na-ewepụ n\'arịrịọ kama izipu ya, nke gaara enye gị obosara ọdịnala na nzuzo kama nke ị rịọrọ.';
$string['settings:embed_migration_target_model'] = 'Model embedding ebumnobi';
$string['settings:embed_migration_target_model_desc'] = 'Aha model a ga-eji mee embedding n\'oge mbufe, dịka <code>voyage-4-large</code>. Ihe efu pụtara na ahazighị mbufe ọ bụla na ibe index RAG anaghị enye nke ọ bụla.';
$string['settings:embed_migration_target_provider'] = 'Onye na-enye embedding ebumnobi';
$string['settings:embed_migration_target_provider_desc'] = 'Hapụ ya efu iji bufee n\'ime onye na-enye ahaziri n\'elu.';
$string['settings:rerank_min_query_chars'] = 'Rerank: ogologo query kacha nta';
$string['settings:rerank_min_query_chars_desc'] = 'Wefuo re-ranker maka query nwere mkpụrụedemede dị otú a ma ọ bụ nke dị mkpụmkpụ karịa. Query dị mkpụmkpụ dị ka okwuisi na re-ranker anaghị agbakwunye ihe ọ bụla n\'elu cosine similarity n\'okwu abụọ ma ọ bụ atọ. A tụrụ ya na setị fixture RAG: iwepụ na 50 nwetara recall 67.7% megide 67.2% maka nke na-agba mgbe niile, na ihe dịka otu ụzọ n\'ụzọ atọ nke ọnụahịa. Tọọ ya na 0 iji rerank query ọ bụla. A na-edekọ rerank ndị e wefuru na log ozi dị ka "[Rerank skipped: short_query]" ka i wee nwee ike ikwenye na ọnụ ụzọ ahụ na-arụ ọrụ.';
$string['settings:spend_export_key'] = 'Igodo mbupụ mmefu';
$string['settings:spend_export_key_desc'] = 'Igodo bearer maka endpoint mbupụ mmefu AI kwa ọnwa na <code>/local/ai_course_assistant/spend_export.php</code>, nke dashboard mmefu na-adọta otu ugboro kwa ọnwa. Hapụ ya efu iji gbanyụọ endpoint ahụ — ọ ga-eweghachi 404 maka arịrịọ ọ bụla. A na-anabata igodo ahụ NAANỊ n\'okpokoro <code>Authorization: Bearer</code>, ọ dịghị mgbe ọ bụla na URL. Mepụta uru ogologo na-enweghị usoro; onye ọ bụla ji ya nwere ike gụọ mmefu AI nke saịtị dum. A na-edekọ mbupụ ọ bụla gara nke ọma na log nyocha plugin.';
