$string['settings:anomaly_digest_floor_usd'] = 'Nchịkọta ihe na-ekwekọghị ekwekọ: mmefu kacha nta a ga-adọ aka ná ntị maka ya (USD)';
$string['settings:anomaly_digest_floor_usd_desc'] = 'Gbochie ịdọ aka ná ntị maka mmefu tokin mgbe awa 24 gara aga fụrụ ego dị ala karịa nke a, n\'agbanyeghị etu mbili pasent ahụ hara ukwuu. Pasent n\'elu obere ntọala bụ mkpọtụ: ịbawanye site na $1 ruo $2 na-agafe ọkwa ọ bụla ma ọ pụtaghị ihe ọ bụla. Debe nke a n\'ọnụọgụ kwa ụbọchị ị ga-achọ n\'ezie ka a kpọtee gị maka ya. 0 na-agbanyụ ala ahụ ma na-adọ aka ná ntị site na pasent naanị. Ọ bụrụ na mmefu ọ bụla n\'ime oge ahụ sitere na model na-enweghị ndenye na kaadị ọnụahịa, enweghị ike ịtụ ọnụahịa ya, a ga-ezipụkwa ịdọ aka ná ntị ahụ n\'agbanyeghị -- model a na-amaghị n\'ime ngwakọta ahụ bụ n\'onwe ya ihe kwesịrị ịhụ.';
$string['settings:prompt_truncated_warning'] = '[[tutorshort]] agbatụwo ọdịnaya kọọsị e nwetara pụọ na prompt ahụ ka o wee daba n\'ọnụọgụ mkpụrụedemede e kenyere, nke ikpeazụ na {$a}. Model ahụ na-azaghachi na ihe ọmụmụ kọọsị dị ntakịrị karịa nke onye nweghachi họọrọ. Bulie ọnụọgụ mkpụrụedemede e kenyere prompt sistem n\'okpuru, ma ọ bụ belata ihe a na-eweghachi.';
$string['settings:radar_batch_enabled'] = 'Zipu akụkọ e haziri n\'ọkwa batch';
$string['settings:radar_batch_enabled_desc'] = 'Agbanyụrụ ya na ndabara. Mgbe agbanyere ya, a na-eziga akụkọ ọ bụla e haziri n\'ọnụahịa batch ma nyefee ya mgbe onye nnye mechara ya, nke nwere ike ime n\'oge ọ bụla n\'ime awa 24; nhazi oge ahụ na-egosi ọnọdụ "ezigara" ruo mgbe ahụ. Nhazi oge ndị onye nnye ha na-enweghị ọkwa batch na-aga n\'ihu n\'usoro nkịtị, ya mere akụkọ agaghị efu n\'ihi ntọala a. Ịgbanyụ ya na-eweghachi nhazi oge niile n\'ụzọ nkịtị n\'ọsọ na-esote, a ga-anakọtakwa ma nyefee batch ọ bụla ka nọ n\'ụzọ.';
$string['settings:radar_batch_heading'] = 'Learning Radar: ọkwa batch offline';
$string['settings:radar_batch_heading_desc'] = 'Enwere ike izipu akụkọ Learning Radar e haziri n\'ọkwa batch offline nke onye nnye AI, nke na-efu 50% ala karịa na tokin ntinye na nke mmepụta ma na-eweta azịza n\'ime ihe ruru awa 24. Naanị akụkọ NDỊ E HAZIRI ruru eru: Learning Radar ozugbo nke ị na-agba site n\'ibe a na-ebuga azịza ya na nchọgharị gị ma na-anọgide n\'usoro nkịtị mgbe niile, otu ahụkwa ka ọ dị n\'ihe ọ bụla nwa akwụkwọ na-eji. A na-edekọ mmefu batch megide aha model nwere <code>batch/</code> n\'ihu ya, ya mere dashboard Mmefu AI na-egosi ọnụahịa mbelata kama ọnụahịa ndepụta.';
$string['settings:soapbox_deprecated_inuse'] = 'Akwụsịla Soapbox. A na-eji PresenterAI dochie ya, nke bụ mgbakwunye ọrụ Moodle dị iche nke na-eme ihe niile Soapbox na-eme, na-apụta na nhọrọ ọrụ, ma na-ekwe ka ị họrọ n\'etiti bọket S3 na nchekwa faịlụ nke Moodle n\'onwe ya, nakwa n\'etiti AI isi nke Moodle na Claude, OpenAI ma ọ bụ Gemini ahaziri ozugbo. Ọ dịghị ihe na-agbanwe na mwepụta a: ọrụ gị, ndekọ olu, ederede okwu, akara na nzaghachi agbanweghị, ntọala njide ka na-arụ ọrụ kpọmkwem dịka mbụ, ọrụ nhicha kwa ụbọchị ka na-agbakwa. E mere atụmatụ iwepụ koodu ahụ na v8.0.0, ọ dịghịkwa mwepụta ga-ewepụ ya tupu PresenterAI enwee ike ibubata ndekọ na akara ndị dị adị. A na-atụfu tebụl nchekwa data ahụ iche na mgbe e mesịrị, n\'ihi na Soapbox anaghị ede ndenye ọ bụla n\'akwụkwọ akara, ya mere tebụl ndị a bụ naanị ebe ndekọ ihe ngosi nke onye mmụta dị. Ihe ị ga-eme: kwụsị iwu kọọsị ọhụrụ na Soapbox ugbu a, wụnye PresenterAI n\'akụkụ ya mgbe ewepụtara ya ma jiri ya maka ọrụ ọhụrụ, ma hapụ kọọsị Soapbox gị ndị dị adị ka ha na-aga n\'ihu ruo mgbe ibubata ga-adị. Ọ dịghị ihe ị ga-agwa ndị mmụta gị ugbu a.';
$string['settings:soapbox_deprecated_off'] = 'Akwụsịla Soapbox, agbanyeghịkwa ya ebe ọ bụla na saịtị a. Hapụ ya ka ọ nọrọ na-agbanyụ. A na-eji PresenterAI dochie ya, nke bụ mgbakwunye ọrụ Moodle dị iche nke na-arụ otu ọrụ ahụ ma na-enye nhọrọ nchekwa na nhọrọ onye nnye AI. E mere atụmatụ iwepụ koodu ahụ na v8.0.0.';
