$string['analytics:total_tokens_hint'] = 'Ọ gụnyere nweghachi: oku embedding na reranking, bụ ndị na-ebu ọnụọgụ a n\'isi na saịtị ebe agbanyere RAG. A na-agụkwa azịza chat ebe a, mana ha bụ obere akụkụ ya. Ọnụọgụ nnọkọ na nke ndị mmụta dị n\'ebe ndị ọzọ n\'ibe a na-atụ naanị chat, nke bụ ihe mere na abụọ ahụ nwere ike ịdị iche nke ukwuu.';
$string['coursesettings:auto_open'] = 'Mmepe akpaaka';
$string['coursesettings:auto_open_desc'] = 'Na-achịkwa ma drawer [[tutorshort]] ọ̀ ga-emepe onwe ya na nke mbụ nwa akwụkwọ rutere na kọọsị a. A na-eso ọnọdụ nleta mbụ kwa kọọsị n\'ime ihe nchọgharị nwa akwụkwọ site na localStorage. Na ndabara, kọọsị a na-eketa ntọala zuru ụwa ọnụ (ugbu a {$a}).';
