$string['coursesettings:english_lock'] = 'Mkpọchi Bekee';
$string['coursesettings:english_lock_desc'] = 'Manye [[tutorshort]] ka ọ zaa mgbe niile n\'asụsụ Bekee maka kọọsị a, n\'agbanyeghị mmasị asụsụ nwa akwụkwọ. Ọ dị mma maka kọọsị mmụta asụsụ Bekee ebe ụmụ akwụkwọ kwesịrị ịmụ ịgụ na ide n\'asụsụ Bekee.';
