$string['coursesettings:voice_tab'] = 'Taabụ Olu';
$string['coursesettings:voice_tab_desc'] = 'Na-achịkwa Taabụ Olu (nhọrọ olu dị na paneli ntọala) maka kọọsị a. Na ndabara ọ na-eketa ntọala zuru ụwa ọnụ (ugbu a {$a}).';
$string['coursesettings:voice_tab_help'] = 'Nọchie ntọala Taabụ Olu zuru ụwa ọnụ maka naanị kọọsị a.';
$string['pricedrift:eol_horizon'] = 'Oke oge ịdọ aka ná ntị maka ọgwụgwụ ndụ (ụbọchị)';
$string['pricedrift:eol_horizon_desc'] = 'Ogologo oge tupu mgbe a ga-amalite ịkọ banyere ezumike ụdị a mara ọkwa ya. Nlele mgbanwe ọnụahịa na-elekọta ọnụahịa; na-enweghị nke a, ọ dịghị ihe na-elekọta ndụ ụdị, ma ezigbo ezumike na-abịa dị ka nkwụsị ọrụ kama ịbụ ịdọ aka ná ntị — ụdị na-anọgide na-arụ ọrụ ma na-anọgide na-agụ ụgwọ ruo mgbe ọ kwụsịrị, mgbe ahụ oku niile na-ada n\'otu oge. Ndabara bụ ụbọchị 60, n\'ihi na ịnọchi ụdị na-arụ ọrụ bụ ntụnyere, mgbanwe ntọala na mbupu, ọ bụghị ọrụ otu ehihie. A na-akọ mgbe niile banyere ezumike nke ụbọchị ya agafeela, n\'agbanyeghị ihe edobere ebe a.';
$string['pricedrift:eol_surfaces'] = 'Ihu API saịtị a na-akpọ';
$string['pricedrift:eol_surfaces_desc'] = 'Kewaa ha site na rikoma, dịka ọmụmaatụ <code>gemini-developer-api,openai-api</code>. A na-adọ aka ná ntị naanị maka ezumike a mara ọkwa ya maka otu n\'ime ihu ndị a; a ka na-egosi ndị ọzọ, na-akọwa ha dị ka nke na-abụghị nke gị. Hapụ ya efu ka ị dọọ aka ná ntị maka ọgwụgwụ ndụ ọ bụla e dekọrọ. Nke a dị n\'ihi ezigbo ihe fọrọ nke nta ka ọ mee: a kọrọ na gemini-2.5-flash ga-ezumike na 2026-10-16, nke bụ eziokwu maka usoro ndụ Vertex AI ma ọ bụghị maka Gemini Developer API nke ngwa a na-akpọ. Ịkpọ mmadụ otu ugboro maka ihe na-adịghị eme na-akụziri ya ileghara oku na-esote anya.';
