$string['settingspage:analytics_link'] = 'Lee Dashboard Analytics';
$string['settingspage:analytics_title'] = 'Dashboard Analytics';
$string['settingspage:rag_explainer'] = 'RAG (Retrieval-Augmented Generation) na-etinye ọdịnaya kọọsị gị na ndeksị ma na-eweta akụkụ ndị dabara mgbe ụmụ akwụkwọ jụrụ ajụjụ, ka AI wee nye azịza gbadoro ụkwụ n\'ihe mmụta gị. Ọ chọrọ igodo API embedding (a na-atụ aro OpenAI). Mgbe ị gbanyechara ya, jiri ibe Nchịkwa RAG tinye kọọsị na ndeksị.';
$string['settingspage:realtime_explainer'] = 'Ọnọdụ Olu Ozugbo na-enye ohere mkparịta ụka olu n\'ụzọ abụọ n\'etiti ụmụ akwụkwọ na AI site n\'iji Realtime API nke OpenAI. Nke a dị iche na ederede-na-okwu nkịtị (TTS), nke na-agụpụta azịza AI n\'olu dara ụda. Olu Ozugbo chọrọ igodo API dị iche ma a na-agụ ụgwọ ya kwa nkeji ọdịyo. Ozugbo ị gbanyere ya n\'ozuzu, ị nwere ike ịgbanwe ya kwa kọọsị n\'ibe ntọala kọọsị ọ bụla.';
