$string['modelregistry:err_badeoldate'] = 'Ụbọchị ọgwụgwụ ndụ ga-abụrịrị ezigbo ụbọchị kalenda edere dị ka YYYY-MM-DD, ma ọ bụ hapụ ya efu.';
$string['modelregistry:err_noeolsurface'] = 'Ụbọchị ọgwụgwụ ndụ chọrọ ihu API e kwuputara ya maka ya. Nkwụsị e kwuputara maka otu ihu adịghị emetụta ihu ọzọ, na ụbọchị enweghị ihu edekọrọ bụ otu ụzọ ọkwa ndụ nke model ị na-adịghị akpọ si aghọ mkpu nkwụsị ụgha. Jiri \'any\' ma ọ bụrụ na ọ metụtara ebe niile.';
$string['modelregistry:field_eol_date'] = 'Ụbọchị ọgwụgwụ ndụ';
$string['modelregistry:field_eol_date_help'] = 'Ụbọchị nkwụsị ma ọ bụ mmechi e kwuputara, dị ka YYYY-MM-DD. Hapụ ya efu mgbe a kwuputabeghị ọgwụgwụ ndụ ọ bụla — efu pụtara na a kwuputabeghị ya, ọ bụghị na ọ dị nchebe. A na-agụ ya dị ka ụbọchị kalenda na UTC, ọ bụghị na mpaghara oge nke gị, ka onye ọ bụla na-agụ ahịrị a wee kwadebe maka otu izu ahụ.';
$string['modelregistry:field_eol_surface'] = 'Ọgwụgwụ ndụ metụtara';
$string['modelregistry:field_eol_surface_help'] = 'Ihu API e kwuputara ụbọchị ahụ maka ya: <code>gemini-developer-api</code>, <code>vertex-ai</code>, <code>openai-api</code>, <code>azure-openai</code>, <code>bedrock</code>, ma ọ bụ <code>any</code> maka ihu niile. A chọrọ ya mgbe ọ bụla etinyere ụbọchị, ọ bụghịkwa akwụkwọ efu: a kọrọ na gemini-2.5-flash ga-akwụsị na 2026-10-16, nke bụ ihe omume ọkwa ndụ nke Vertex AI, ọ bụghị Gemini Developer API nke saịtị a na-akpọ. Na-enweghị ihu ahụ, ụbọchị ahụ na-akpọ mkpu nkwụsị mmepụta banyere model na-agaghị ebe ọ bụla. Depụta ihu ndị saịtị a na-akpọ n\'ezie n\'okpuru Mgbanwe ọnụahịa ka ndị na-abụghị nke gị wee nọgide bụrụ naanị ozi.';
$string['modelregistry:finding_eol'] = 'Model na-eru ọgwụgwụ ndụ';
$string['modelregistry:status_retired'] = 'Akwụsịrị';
$string['privacy:metadata:bench'] = 'Ọsọ ntule onye na-enye: nsonaazụ ntụnyere model nke onye nchịkwa saịtị mepụtara. Naanị data nkeonwe dị bụ njirimara onye nchịkwa malitere ọsọ ahụ. Ahịrị ndị a bụ nhazi saịtị kama ịbụ data nkeonwe gbasara onye mmụta, ya mere a naghị etinye ha na mbupụ data, a naghịkwa ewepụ ha mgbe onye ọrụ rịọrọ mkpochapụ.';
$string['privacy:metadata:bench:createdby'] = 'Onye nchịkwa saịtị malitere ọsọ ntule a. Ọ dị efu mgbe e si na ahịrị iwu malite ọsọ ahụ.';
$string['privacy:metadata:models'] = 'Ntinye registry model: ọnụahịa na nnochi ikike kwa model nke onye nchịkwa saịtị na-elekọta. Naanị data nkeonwe dị bụ njirimara onye nchịkwa chekwara ntinye ahụ ikpeazụ. Ahịrị ndị a bụ nhazi saịtị kama ịbụ data nkeonwe gbasara onye mmụta, ya mere a naghị etinye ha na mbupụ data, a naghịkwa ewepụ ha mgbe onye ọrụ rịọrọ mkpochapụ.';
$string['privacy:metadata:models:addedby'] = 'Onye nchịkwa saịtị chekwara ntinye registry model a ikpeazụ. Ọ dị efu mgbe feed ọnụahịa na-akpaghị aka dere ntinye ahụ.';
$string['privacy:metadata:pricesrc'] = 'Nkọwa feed ọnụahịa: ndepụta ọnụahịa onye na-ere ahịa nke onye nchịkwa saịtị hazịrị plugin ka ọ na-eweta. Naanị data nkeonwe dị bụ njirimara onye nchịkwa tinyere feed ahụ. Ahịrị ndị a bụ nhazi saịtị kama ịbụ data nkeonwe gbasara onye mmụta, ya mere a naghị etinye ha na mbupụ data, a naghịkwa ewepụ ha mgbe onye ọrụ rịọrọ mkpochapụ.';
$string['privacy:metadata:pricesrc:addedby'] = 'Onye nchịkwa saịtị tinyere feed ọnụahịa a. Ọ dị efu mgbe feed ahụ so na plugin.';
$string['privacy:metadata:sbx_assign'] = 'Nkenye ngosi Soapbox: ọrụ ndị onye nkuzi na-ehazi maka kọọsị. Naanị data nkeonwe dị bụ njirimara onye ọrụ dezịrị nkenye ahụ ikpeazụ. Ahịrị ndị a bụ nhazi kọọsị kama ịbụ data nkeonwe gbasara onye mmụta, ya mere a naghị etinye ha na mbupụ data, a naghịkwa ewepụ ha mgbe onye ọrụ rịọrọ mkpochapụ, nke ga-agbanwe nkenye ndị ọzọ na-amụ ihe ka na-arụ ọrụ na ya.';
$string['privacy:metadata:sbx_assign:usermodified'] = 'Onye ọrụ dezịrị nkenye ngosi a ikpeazụ.';
$string['redash:err_deanonymized_disabled'] = 'Agbanyụrụ mbupụ na-ezoghị aha. Gbanye ntọala plugin "Allow de-anonymized export" ka i kwe ka anonymize=0.';
$string['redash:err_invalid_key'] = 'Igodo API ezighị ezi';
$string['redash:err_method_not_allowed'] = 'Ekweghị ụzọ a';
