$string['starters:howto_builtin'] = '<strong>Mmalite e wuru n\'ime</strong> bụ nke sistemu na-achịkwa. Ị nwere ike ịgbanye ma ọ bụ gbanyụọ ha, gbanwee aịkọn ha, ma hazigharịa ha, mana ị nweghị ike ihichapụ ha.';
$string['starters:howto_conditional'] = '<strong>Ọhụhụ nwere ọnọdụ:</strong> họrọ "Naanị mgbe agbanyere TTS" maka mmalite ụda, ma ọ bụ "Naanị mgbe agbanyere Realtime" maka mmalite ịkpọpụta okwu. Ọ bụrụ na agbanyụrụ atụmatụ a chọrọ, a ga-ezochi mmalite ahụ n\'ebe ụmụ akwụkwọ nọ.';
$string['starters:howto_custom'] = '<strong>Mmalite ahaziri onwe</strong> bụ ndị ị mepụtara. Pịa "{$a}" n\'okpuru iji mepụta otu. Ị nwere ike idezi ihe niile: aha, prompt, aịkọn, na ọnọdụ ọhụhụ.';
$string['starters:howto_heading'] = 'Otu esi eji ibe a';
$string['starters:howto_overrides'] = '<strong>Nnochi kwa kọọsị:</strong> mgbe ị hazichara mmalite ebe a, gaa na ibe ntọala nke kọọsị ọ bụla ka ị gbanye ma ọ bụ gbanyụọ mmalite ndị akọwapụtara maka kọọsị ahụ.';
